// Valida el payload de aula/camara/energia: {"v":12.1,"i":0.85,"p":10.3}
// Salida 1: lectura válida (msg.params para el INSERT). Salida 2: descartada.
const MAX_CARACTERES = 1024;
const RANGOS = { v: [0, 30], i: [0, 10], p: [0, 300] }; // V, A, W

function descartar(motivo) {
    return [null, { payload: "Descartado, " + motivo }];
}

// Una lectura nunca se retiene (contrato MQTT, sección 1): un retenido sería una
// lectura falsa que se repetiría en cada conexión. Se descarta y se avisa.
if (msg.retain === true) {
    node.warn("Descartado mensaje retenido en " + msg.topic + ": las lecturas no se retienen");
    return descartar("mensaje retenido en " + msg.topic + " (las lecturas no se retienen)");
}
// Payload vacío: no es una lectura. Es el mensaje en vivo que provoca la limpieza de
// retenidos en cada conexión al broker; se ignora en silencio.
if (msg.payload === "" || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0)) {
    return null;
}
if (typeof msg.payload !== "string") {
    return descartar("el payload no es texto");
}
if (msg.payload.length > MAX_CARACTERES) {
    return descartar("payload de " + msg.payload.length + " caracteres (máximo " + MAX_CARACTERES + ")");
}
const resumen = msg.payload.slice(0, 200);

let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (e) {
    return descartar("no es JSON: " + resumen);
}
if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
    return descartar("no es un objeto JSON: " + resumen);
}
for (const campo of Object.keys(RANGOS)) {
    const x = datos[campo];
    if (typeof x !== "number" || !Number.isFinite(x)) {
        return descartar("falta " + campo + " numérico: " + resumen);
    }
    if (x < RANGOS[campo][0] || x > RANGOS[campo][1]) {
        return descartar(campo + " fuera de rango [" + RANGOS[campo] + "]: " + resumen);
    }
}
msg.params = [datos.v, datos.i, datos.p];
return [msg, null];

// GET /api/metricas/energia?limite=N&desde=<fecha ISO 8601>
// limite: entero >= 1, 100 por defecto, tope de 1000.
// desde: solo lecturas desde esa fecha. Formatos: 2026-11-04, 2026-11-04T10:00,
// 2026-11-04T10:00:00Z, 2026-11-04T10:00:00.5-06:00 (años 1970 a 9999).
const POR_DEFECTO = 100;
const MAXIMO = 1000;
const ISO_8601 = /^[0-9]{4}-[0-9]{2}-[0-9]{2}(T[0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]{1,9})?)?(Z|[+-][0-9]{2}:[0-9]{2})?)?$/;
const q = msg.req.query || {};

function rechazar(texto) {
    msg.statusCode = 400;
    msg.payload = { error: texto };
    return [null, msg];
}

let limite = POR_DEFECTO;
if (q.limite !== undefined) {
    if (typeof q.limite !== "string" || !/^[0-9]+$/.test(q.limite) || Number(q.limite) < 1) {
        return rechazar("limite debe ser un entero mayor o igual a 1");
    }
    limite = Math.min(Number(q.limite), MAXIMO);
}

let desde = null;
if (q.desde !== undefined) {
    const fecha = (typeof q.desde === "string" && ISO_8601.test(q.desde)) ? new Date(q.desde) : new Date(NaN);
    // El año se revisa tras convertir a UTC: una zona horaria puede empujar 9999 a 10000.
    if (Number.isNaN(fecha.getTime()) || fecha.getUTCFullYear() < 1970 || fecha.getUTCFullYear() > 9999) {
        return rechazar("desde debe ser una fecha ISO 8601 entre 1970 y 9999, por ejemplo 2026-11-04T10:00:00Z");
    }
    desde = fecha.toISOString();
}

msg.params = [desde, limite];
return [msg, null];

// Error al consultar la base de datos: se registra y se responde 500.
node.warn("GET /api/metricas/energia falló: " + (msg.error && msg.error.message));
msg.statusCode = 500;
msg.payload = { error: "No se pudo consultar la base de datos" };
return msg;

// GET /api/metricas/latencia?limite=N&desde=<fecha ISO 8601>
// Mismos parámetros y reglas que "Validar limite y desde" de la ruta de energía (una prueba comprueba que
// sigan iguales).
// limite: entero >= 1, 100 por defecto, tope de 1000.
// desde: solo mediciones desde esa fecha. Formatos: 2026-11-04, 2026-11-04T10:00,
// 2026-11-04T10:00:00Z, 2026-11-04T10:00:00.5-06:00 (años 1970 a 9999).
const POR_DEFECTO = 100;
const MAXIMO = 1000;
const ISO_8601 = /^[0-9]{4}-[0-9]{2}-[0-9]{2}(T[0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]{1,9})?)?(Z|[+-][0-9]{2}:[0-9]{2})?)?$/;
const q = msg.req.query || {};

function rechazar(texto) {
    msg.statusCode = 400;
    msg.payload = { error: texto };
    return [null, msg];
}

let limite = POR_DEFECTO;
if (q.limite !== undefined) {
    if (typeof q.limite !== "string" || !/^[0-9]+$/.test(q.limite) || Number(q.limite) < 1) {
        return rechazar("limite debe ser un entero mayor o igual a 1");
    }
    limite = Math.min(Number(q.limite), MAXIMO);
}

let desde = null;
if (q.desde !== undefined) {
    const fecha = (typeof q.desde === "string" && ISO_8601.test(q.desde)) ? new Date(q.desde) : new Date(NaN);
    // El año se revisa tras convertir a UTC: una zona horaria puede empujar 9999 a 10000.
    if (Number.isNaN(fecha.getTime()) || fecha.getUTCFullYear() < 1970 || fecha.getUTCFullYear() > 9999) {
        return rechazar("desde debe ser una fecha ISO 8601 entre 1970 y 9999, por ejemplo 2026-11-04T10:00:00Z");
    }
    desde = fecha.toISOString();
}

msg.params = [desde, limite];
return [msg, null];

// Error al consultar la base de datos: se registra solo el SQLSTATE (o un mensaje truncado y sin
// secuencias de 9 dígitos) y se responde 500 sin detalle.
const error = msg.error || {};
let causa;
if (typeof error.code === "string" && /^[0-9A-Z]{5}$/.test(error.code)) {
    causa = "SQLSTATE " + error.code;
} else if (typeof error.message === "string" && error.message !== "") {
    causa = error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120);
} else {
    causa = "error desconocido";
}
node.warn("GET /api/metricas/latencia falló: " + causa);
msg.statusCode = 500;
msg.payload = { error: "No se pudo consultar la base de datos" };
return msg;

// Llega el estado del nodo "Borrar retenido". Solo interesa "conectado" (verde, punto):
// es el estado que mqtt out emite cuando ya puede publicar, al conectar y al reconectar.
const s = msg.status || {};
if (s.fill !== "green" || s.shape !== "dot") {
    return null;
}
// Un mensaje por tópico, con payload vacío y retain: borra el retenido.
const topicos = ["aula/actuador/cmd", "aula/sesion/cmd", "aula/vision/cmd", "aula/camara/pir", "aula/camara/energia", "aula/vision/resultado"];
node.log("Conectado al broker: se piden borrar los retenidos de " + topicos.join(", "));
return [topicos.map((topic) => ({ topic: topic, payload: "", qos: 1, retain: true }))];

// Respuesta de GET /api/galeria, en el formato que lee el servicio de visión
// (orangepi/vision/src/gallery_store.cpp): {"embeddings":[{"cuenta":"320068234","embedding":[...]}]}
// Cada fila trae el embedding como texto de pgvector ("[0.1,0.2,...]"), que es JSON válido.
// Nunca se registra ni se devuelve en un error el contenido del embedding: es un dato biométrico.
const filas = msg.payload;
if (!Array.isArray(filas)) {
    throw new Error("la consulta de la galería no devolvió filas");
}
const embeddings = filas.map((fila) => {
    let valores;
    try {
        valores = JSON.parse(fila.embedding);
    } catch (e) {
        valores = null;
    }
    if (!Array.isArray(valores) || valores.length === 0 || !valores.every((x) => typeof x === "number" && Number.isFinite(x))) {
        // Sin la cuenta en el mensaje: los errores terminan en el log.
        throw new Error("un embedding de la galería no es un arreglo numérico");
    }
    return { cuenta: fila.cuenta, embedding: valores };
});
msg.statusCode = 200;
msg.payload = { embeddings: embeddings };
return msg;

// GET /api/alumnos?grupo=<grupo>
// grupo (opcional): de 1 a 40 caracteres, sin caracteres de control ni de formato
// invisibles (ancho cero, marca de orden de bytes...). Sin grupo se
// listan todos los alumnos.
const MAX_GRUPO = 40;
const q = msg.req.query || {};

function rechazar(texto) {
    msg.statusCode = 400;
    msg.payload = { error: texto };
    return [null, msg];
}

let grupo = null;
if (q.grupo !== undefined) {
    if (typeof q.grupo !== "string") {
        return rechazar("grupo debe indicarse una sola vez, como texto");
    }
    grupo = q.grupo.normalize("NFC").trim();
    if (grupo === "") {
        return rechazar("grupo no puede estar vacío");
    }
    if ([...grupo].length > MAX_GRUPO) {
        return rechazar("grupo no puede tener más de " + MAX_GRUPO + " caracteres");
    }
    if (/[\p{Cc}\p{Cf}]/u.test(grupo)) {
        return rechazar("grupo no puede llevar caracteres de control ni invisibles");
    }
}
msg.params = [grupo];
return [msg, null];

// POST /api/alumnos/importar[?existentes=actualizar|omitir]
// Cuerpo: el CSV de la lista maestra, crudo (Content-Type: text/csv; charset=utf-8),
// con el encabezado no_cuenta,nombre,grupo. Se valida el archivo completo antes de
// tocar la base: si una fila es inválida, 400 con la lista de filas y nada se importa.
// Salida 1: archivo válido (msg.csv = filas, msg.modo, msg.params = [cuentas]).
// Salida 2: respuesta de error (400, 413 o 415).
const MAX_BYTES = 256 * 1024; // el mismo tope que LIMITE_CUERPO_BYTES de nodered/autenticacion-api.js
const MAX_FILAS = 500;
const MAX_NOMBRE = 120;
const MAX_GRUPO = 40;
const MAX_ERRORES = 100; // filas inválidas que se listan en la respuesta
const ENCABEZADO = ["no_cuenta", "nombre", "grupo"];
// Caracteres de control (\n incluido) e invisibles de formato (ancho cero, marca de
// orden de bytes intermedia, inversión de texto...).
const CONTROL = /[\p{Cc}\p{Cf}]/u;

function rechazar(codigo, cuerpo) {
    msg.statusCode = codigo;
    msg.payload = cuerpo;
    return [null, msg];
}

// Solo text/csv (con parámetros como charset). Los tipos que un formulario HTML de
// otro sitio puede enviar sin permiso (text/plain, urlencoded, multipart) se
// rechazan: es la primera capa contra CSRF; la segunda está en autenticacion-api.js.
const tipo = String(msg.req.headers["content-type"] || "").split(";")[0].trim().toLowerCase();
if (tipo !== "text/csv") {
    return rechazar(415, { error: "El Content-Type debe ser text/csv (por ejemplo, text/csv; charset=utf-8)" });
}

const q = msg.req.query || {};
let modo = null;
if (q.existentes !== undefined) {
    if (q.existentes !== "actualizar" && q.existentes !== "omitir") {
        return rechazar(400, { error: "existentes debe ser actualizar u omitir" });
    }
    modo = q.existentes;
}

let texto;
let bytes;
if (typeof msg.payload === "string") {
    texto = msg.payload;
    bytes = Buffer.byteLength(texto, "utf8");
} else if (Buffer.isBuffer(msg.payload)) {
    texto = msg.payload.toString("utf8");
    bytes = msg.payload.length;
} else {
    return rechazar(400, { error: "El cuerpo debe ser el archivo CSV crudo, con Content-Type: text/csv" });
}
if (bytes > MAX_BYTES) {
    return rechazar(413, { error: "El archivo pesa " + bytes + " bytes (máximo " + MAX_BYTES + ")" });
}
if (texto.includes("�")) {
    return rechazar(400, { error: "El archivo no es UTF-8 válido: guárdalo como CSV UTF-8" });
}
if (texto.charCodeAt(0) === 0xFEFF) {
    texto = texto.slice(1); // BOM de UTF-8 (lo escribe Excel)
}

// Lector de CSV (RFC 4180): comas, campos entre comillas con "" para una comilla,
// saltos de línea \n, \r\n o \r. Las líneas en blanco se ignoran. Cada registro
// guarda la línea donde empieza (el encabezado es la línea 1).
function leerRegistros(t) {
    const registros = [];
    let campos = [];
    let campo = "";
    let enComillas = false;
    let cerradas = false; // el campo ya cerró sus comillas
    let conComillas = false; // el registro abrió comillas alguna vez
    let problema = null;
    let linea = 1;
    let lineaInicio = 1;

    function cerrarRegistro() {
        campos.push(campo);
        const enBlanco = campos.length === 1 && campos[0].trim() === "" && !conComillas;
        if (!enBlanco) {
            registros.push({ linea: lineaInicio, campos: campos, problema: problema });
        }
        campos = [];
        campo = "";
        cerradas = false;
        conComillas = false;
        problema = null;
        lineaInicio = linea;
    }

    for (let i = 0; i < t.length; i++) {
        const c = t[i];
        if (enComillas) {
            if (c === '"') {
                if (t[i + 1] === '"') {
                    campo += '"';
                    i++;
                } else {
                    enComillas = false;
                    cerradas = true;
                }
            } else {
                // Un \r\n cuenta una vez (por su \n); un \r suelto también es un salto.
                if (c === "\n" || (c === "\r" && t[i + 1] !== "\n")) {
                    linea++;
                }
                campo += c;
            }
        } else if (c === ",") {
            campos.push(campo);
            campo = "";
            cerradas = false;
        } else if (c === "\r" || c === "\n") {
            if (c === "\r" && t[i + 1] === "\n") {
                i++;
            }
            linea++;
            cerrarRegistro();
        } else if (c === '"') {
            if (campo === "" && !cerradas) {
                enComillas = true;
                conComillas = true;
            } else {
                problema = problema || "comilla inesperada: un campo con comillas debe empezar con ellas";
            }
        } else if (cerradas) {
            if (c !== " " && c !== "\t") {
                problema = problema || "hay texto después de cerrar las comillas de un campo";
            }
        } else {
            campo += c;
        }
    }
    if (enComillas) {
        problema = problema || "comillas sin cerrar";
    }
    if (campo !== "" || campos.length > 0 || conComillas) {
        cerrarRegistro();
    }
    return registros;
}

const registros = leerRegistros(texto);
if (registros.length === 0) {
    return rechazar(400, { error: "El archivo está vacío" });
}
const encabezado = registros[0].campos.map((x) => x.trim().toLowerCase());
if (registros[0].problema !== null || encabezado.join(",") !== ENCABEZADO.join(",")) {
    return rechazar(400, { error: "La primera línea debe ser el encabezado " + ENCABEZADO.join(",") + ", separado por comas. Guarda el archivo como CSV UTF-8 (delimitado por comas): Excel en español exporta con punto y coma" });
}
const datos = registros.slice(1);
if (datos.length === 0) {
    return rechazar(400, { error: "El archivo no tiene filas de alumnos después del encabezado" });
}
if (datos.length > MAX_FILAS) {
    return rechazar(400, { error: "El archivo tiene " + datos.length + " filas (máximo " + MAX_FILAS + ")" });
}

const filas = [];
const errores = [];
const lineaDeCuenta = new Map();
for (const registro of datos) {
    const problemas = [];
    if (registro.problema !== null) {
        problemas.push(registro.problema);
    }
    if (registro.campos.length !== ENCABEZADO.length) {
        problemas.push("se esperaban " + ENCABEZADO.length + " columnas y hay " + registro.campos.length);
    } else {
        // NFC: un acento escrito como letra + marca (macOS) queda como un solo carácter.
        const [cuenta, nombre, grupo] = registro.campos.map((x) => x.normalize("NFC").trim());
        if (!/^[0-9]{9}$/.test(cuenta)) {
            problemas.push("no_cuenta debe tener exactamente 9 dígitos");
        } else if (lineaDeCuenta.has(cuenta)) {
            problemas.push("no_cuenta repetida (ya aparece en la fila " + lineaDeCuenta.get(cuenta) + ")");
        } else {
            lineaDeCuenta.set(cuenta, registro.linea);
        }
        if (nombre === "") {
            problemas.push("nombre vacío");
        } else if ([...nombre].length > MAX_NOMBRE) {
            problemas.push("nombre de más de " + MAX_NOMBRE + " caracteres");
        } else if (CONTROL.test(nombre)) {
            problemas.push("nombre con saltos de línea o caracteres de control o invisibles");
        }
        if (grupo === "") {
            problemas.push("grupo vacío");
        } else if ([...grupo].length > MAX_GRUPO) {
            problemas.push("grupo de más de " + MAX_GRUPO + " caracteres");
        } else if (CONTROL.test(grupo)) {
            problemas.push("grupo con saltos de línea o caracteres de control o invisibles");
        }
        if (problemas.length === 0) {
            filas.push({ cuenta: cuenta, nombre: nombre, grupo: grupo });
        }
    }
    if (problemas.length > 0) {
        errores.push({ fila: registro.linea, error: problemas.join("; ") });
    }
}
if (errores.length > 0) {
    return rechazar(400, {
        error: "El archivo tiene filas inválidas: no se importó nada",
        total_errores: errores.length,
        filas: errores.slice(0, MAX_ERRORES)
    });
}

msg.csv = filas;
msg.modo = modo;
msg.params = [filas.map((f) => f.cuenta)];
msg.payload = null;
return [msg, null];

// Llegan las cuentas del CSV que ya existen en alumnos (msg.payload) y el CSV ya
// validado (msg.csv). La decisión sobre las existentes es del profesor:
// sin ?existentes= y con alguna cuenta existente, 409 y no se escribe nada.
// Salida 1: se escribe (msg.params para el INSERT/UPDATE). Salida 2: respuesta 409.
const existentes = msg.payload;
if (!Array.isArray(existentes)) {
    throw new Error("la consulta de cuentas existentes no devolvió filas");
}
if (existentes.length > 0 && msg.modo === null) {
    const delCsv = new Map(msg.csv.map((f) => [f.cuenta, f]));
    msg.statusCode = 409;
    msg.payload = {
        escrito: false, // no se importó nada
        error: "Hay cuentas del archivo que ya existen: no se importó nada. Reenvía con ?existentes=actualizar (cambia solo nombre y grupo) o ?existentes=omitir (importa solo las nuevas)",
        existentes: existentes.map((e) => {
            const f = delCsv.get(e.cuenta);
            return {
                cuenta: e.cuenta,
                actual: { nombre: e.nombre_actual, grupo: e.grupo_actual },
                csv: { nombre: f.nombre, grupo: f.grupo },
                cambia: e.nombre_actual !== f.nombre || e.grupo_actual !== f.grupo,
                tiene_rostro: e.tiene_rostro === true
            };
        }),
        opciones: ["actualizar", "omitir"]
    };
    return [null, msg];
}
msg.params = [
    msg.csv.map((f) => f.cuenta),
    msg.csv.map((f) => f.nombre),
    msg.csv.map((f) => f.grupo),
    msg.modo === "actualizar" ? "actualizar" : "omitir"
];
return [msg, null];

// Conteos de la importación (una sola sentencia, una sola transacción).
// Sin ?existentes= (msg.modo null) la decisión sobre las existentes no se tomó, y
// "Decidir importación" ya comprobó que no había ninguna. Si aun así hay omitidas, otra
// importación insertó esa cuenta entre la comprobación y la escritura (el INSERT usa
// ON CONFLICT DO NOTHING): no se responde 200 en silencio, sino 409 con los conteos. Las
// filas nuevas del archivo sí quedaron escritas; reenviar con ?existentes= es seguro.
const conteo = Array.isArray(msg.payload) ? msg.payload[0] : undefined;
if (!conteo) {
    throw new Error("la importación no devolvió conteos");
}
if (msg.modo === null && conteo.omitidas > 0) {
    msg.statusCode = 409;
    msg.payload = {
        escrito: true, // las filas nuevas ya se escribieron
        error: "Otra importación agregó cuentas del archivo mientras tanto: se omitieron " + conteo.omitidas + " y se insertaron " + conteo.insertadas + ". Reenvía el archivo con ?existentes=actualizar u omitir",
        insertadas: conteo.insertadas,
        actualizadas: conteo.actualizadas,
        omitidas: conteo.omitidas,
        total: msg.csv.length
    };
    return msg;
}
msg.statusCode = 200;
msg.payload = {
    insertadas: conteo.insertadas,
    actualizadas: conteo.actualizadas,
    omitidas: conteo.omitidas,
    total: msg.csv.length
};
return msg;

// Error al consultar o escribir en la base de datos: se registra solo el código
// SQLSTATE del error (cinco caracteres). Nunca msg, msg.params, el detalle de Postgres
// ("Key (no_cuenta)=(...)") ni el mensaje completo: pueden llevar números de cuenta,
// nombres o embeddings. Sin SQLSTATE, un mensaje truncado y sin secuencias de 9 dígitos.
// Se responde 500.
const error = msg.error || {};
let causa;
if (typeof error.code === "string" && /^[0-9A-Z]{5}$/.test(error.code)) {
    causa = "SQLSTATE " + error.code;
} else if (typeof error.message === "string" && error.message !== "") {
    causa = error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120);
} else {
    causa = "error desconocido";
}
node.warn(msg.req.method + " " + msg.req.path + " falló: " + causa);
msg.statusCode = 500;
msg.payload = { error: "No se pudo completar la operación en la base de datos" };
return msg;

// POST /api/enrolamiento {"cuenta":"320068234","consentimiento":true}
// Cuerpo JSON (Content-Type: application/json). Valida la entrada, comprueba que no
// haya otro registro abierto y aparta el lugar de la inscripción ANTES de tocar la
// base: esta función corre sin interrupción, así que dos peticiones a la vez (doble
// clic, segunda pestaña) no pueden pasar las dos, y la segunda no escribe nada.
// Si la base falla o el alumno no sirve, el lugar se libera ("Abrir inscripción y
// ordenar enrolar" y "Cerrar y responder 500").
// Salida 1: sigue al UPDATE del consentimiento (msg.params, msg.reserva).
// Salida 2: respuesta de error (400, 409 o 415). El 409 lleva motivo: registro_abierto o prueba_pendiente.
const CUENTA = /^[0-9]{9}$/;
const POSES = ["frente", "izquierda", "derecha", "arriba", "frente_2"];

function rechazar(codigo, cuerpo) {
    msg.statusCode = codigo;
    msg.payload = cuerpo;
    return [null, msg];
}

// Solo application/json: los tipos que un formulario HTML de otro sitio puede enviar
// sin permiso (text/plain, urlencoded) se rechazan; la segunda capa contra CSRF está
// en autenticacion-api.js (X-Pase-Lista y el mismo origen).
const tipo = String(msg.req.headers["content-type"] || "").split(";")[0].trim().toLowerCase();
if (tipo !== "application/json") {
    return rechazar(415, { error: "El Content-Type debe ser application/json" });
}
const cuerpo = msg.payload;
if (cuerpo === null || typeof cuerpo !== "object" || Array.isArray(cuerpo)) {
    return rechazar(400, { error: "El cuerpo debe ser un objeto JSON con cuenta y consentimiento" });
}
if (typeof cuerpo.cuenta !== "string" || !CUENTA.test(cuerpo.cuenta)) {
    return rechazar(400, { error: "cuenta debe ser un texto de 9 dígitos" });
}
if (cuerpo.consentimiento !== true) {
    return rechazar(400, { error: "Sin consentimiento no se registra el rostro: consentimiento debe ser true" });
}
const abierta = flow.get("inscripcion");
if (abierta && abierta.abierto === true) {
    return rechazar(409, { error: "Ya hay un registro abierto: termínalo o cancélalo antes de iniciar otro", motivo: "registro_abierto" });
}

// Una prueba de reconocimiento pendiente (POST /api/enrolamiento/probar, 15 s como máximo) deja a la visión ocupada: un
// enrolar ahora recibiría "ocupado" y el registro se cerraría con error. Misma expresión que esa ruta: un salto
// del reloj hacia atrás no bloquea.
const prueba = flow.get("prueba");
const espera = prueba && typeof prueba.solicitado_ms === "number" ? Date.now() - prueba.solicitado_ms : null;
if (prueba && prueba.pendiente === true && espera !== null && espera >= 0 && espera < 15 * 1000) {
    return rechazar(409, { error: "Hay una prueba de reconocimiento en curso: espera su resultado antes de iniciar un registro", motivo: "prueba_pendiente" });
}

const ahora = Date.now();
const id = "r" + ahora + "-" + Math.random().toString(36).slice(2, 8);
flow.set("inscripcion", {
    id: id,
    abierto: true,
    apartada: true, // hasta que la base confirme el consentimiento y se publique la orden
    cuenta: cuerpo.cuenta,
    nombre: null,
    estado: "esperando_vision",
    motivo: null,
    poses: POSES.map((pose) => ({ pose: pose, estado: "pendiente", motivo: null, miniatura: null })),
    advertencia: null,
    inicio_ms: ahora,
    actualizado_ms: ahora,
    // Ticks de 15 s sin progreso (reloj monotónico de los temporizadores, ver "Vencer inscripción").
    ticks: 0
});
msg.reserva = id;
msg.params = [cuerpo.cuenta];
msg.payload = null;
return [msg, null];

// Respuesta del UPDATE del consentimiento: una fila {existe, nombre, tiene_rostro,
// actualizadas}, leída y escrita en la misma sentencia. Aquí se decide:
//   - la cuenta no existe: 404;
//   - el alumno ya tiene rostro: 409. Volver a registrar a alguien con rostro exige
//     antes retirarlo (plan, sección 5.4): el embedding anterior no se pisa nunca;
//   - si no, el consentimiento ya quedó escrito: se abre la inscripción, se ordena
//     enrolar a la visión y se responde 202.
// Salida 1: respuesta HTTP. Salida 2: orden a aula/vision/cmd.
// Salida 3: revertir el consentimiento (solo si el lugar se perdió mientras tanto).
const fila = Array.isArray(msg.payload) ? msg.payload[0] : undefined;
if (!fila) {
    throw new Error("la consulta del consentimiento no devolvió filas");
}
const cuenta = msg.params[0];

function liberar() {
    const i = flow.get("inscripcion");
    if (i && i.id === msg.reserva && i.apartada === true) {
        flow.set("inscripcion", undefined);
    }
}

function responder(codigo, cuerpo) {
    msg.statusCode = codigo;
    msg.payload = cuerpo;
    return msg;
}

if (fila.existe === 0) {
    liberar();
    return [responder(404, { error: "No existe un alumno con esa cuenta" }), null, null];
}
if (fila.tiene_rostro === true) {
    liberar();
    return [responder(409, {
        error: "El alumno ya tiene rostro registrado: retíralo antes de volver a registrarlo",
        motivo: "tiene_rostro"
    }), null, null];
}
if (fila.actualizadas !== 1) {
    liberar();
    throw new Error("el consentimiento no se escribió");
}

const insc = flow.get("inscripcion");
if (!insc || insc.id !== msg.reserva || insc.abierto !== true) {
    // Mientras se escribía, el lugar se cerró (cancelación, reinicio de los flujos):
    // sin inscripción no hay quien reciba el progreso, y el consentimiento ya quedó escrito.
    return [responder(409, { error: "El registro se interrumpió antes de empezar: vuelve a intentarlo", motivo: "interrumpido" }), null, { params: [cuenta] }];
}
// El consentimiento se escribió porque la cuenta no tenía rostro: un retiro tardío pendiente de
// ella ya no hace falta (y borraría el rostro del registro nuevo).
const pendientes = flow.get("retiros_pendientes", "persistente");
if (Array.isArray(pendientes) && pendientes.some((p) => p && p.cuenta === cuenta)) {
    const resto = pendientes.filter((p) => !(p && p.cuenta === cuenta));
    flow.set("retiros_pendientes", resto.length > 0 ? resto : undefined, "persistente");
}
insc.nombre = fila.nombre;
insc.apartada = false;
insc.actualizado_ms = Date.now();
insc.ticks = 0;
flow.set("inscripcion", insc);

const orden = {
    topic: "aula/vision/cmd",
    payload: JSON.stringify({ accion: "enrolar", cuenta: cuenta, nombre: fila.nombre }),
    qos: 1,
    retain: false
};
return [responder(202, { cuenta: cuenta, nombre: fila.nombre, abierto: true }), orden, null];

// POST /api/enrolamiento/cancelar
// Con un registro abierto: lo cierra en memoria (desde ese instante un embedding tardío
// ya no se acepta), ordena cancelar a la visión y revierte el consentimiento (el alumno
// no tiene rostro: solo se registra uno cuando no lo tiene). La respuesta sale cuando
// la base confirma ("Tras revertir").
// Sin registro abierto responde 200 con cancelado: false y no publica nada: es
// idempotente. Un 409 haría fallar al frontend cuando el registro terminó justo antes
// de pulsar "Cancelar", y lo que la persona quiere (que no haya registro abierto) ya
// se cumple.
// Salida 1: respuesta HTTP. Salida 2: orden a aula/vision/cmd. Salida 3: revertir el consentimiento.
const insc = flow.get("inscripcion");
if (!insc || insc.abierto !== true) {
    msg.statusCode = 200;
    msg.payload = { cancelado: false, abierto: false };
    return [msg, null, null];
}
insc.abierto = false;
insc.apartada = false;
insc.estado = "cancelado";
insc.motivo = null;
// La miniatura no sobrevive al registro: al cerrarlo, se borra del contexto.
for (const pose of insc.poses) {
    pose.miniatura = null;
}
insc.actualizado_ms = Date.now();
flow.set("inscripcion", insc);

msg.params = [insc.cuenta];
const orden = {
    topic: "aula/vision/cmd",
    payload: JSON.stringify({ accion: "cancelar", cuenta: insc.cuenta }),
    qos: 1,
    retain: false
};
return [null, orden, msg];

// GET /api/enrolamiento/estado: solo lectura. Devuelve el estado del último registro
// (abierto o recién cerrado, para que el frontend vea cómo terminó):
// {abierto, cuenta, nombre, estado, motivo, poses:[{pose,estado,motivo,miniatura}],
//  advertencia:{parecido_a}|null, duplicado_de:"<cuenta>"|null, inicio, actualizado}
// `duplicado_de` solo va con estado "error" y motivo "duplicado": la cuenta que ya tiene ese rostro.
// Sin ningún registro desde que arrancó Node-RED: abierto false, estado "sin_registro".
// Cada campo se copia por su nombre: nunca sale de aquí un embedding. La miniatura de la
// pose sí sale (es lo que el navegador muestra), pero solo mientras el registro está
// abierto: es efímera, no se guarda en la base de datos ni en ningún archivo.
const insc = flow.get("inscripcion");
const iso = (ms) => new Date(ms).toISOString();

if (!insc) {
    msg.payload = {
        abierto: false,
        cuenta: null,
        nombre: null,
        estado: "sin_registro",
        motivo: null,
        poses: [],
        advertencia: null,
        duplicado_de: null,
        inicio: null,
        actualizado: null
    };
} else {
    msg.payload = {
        abierto: insc.abierto === true,
        cuenta: insc.cuenta,
        nombre: insc.nombre,
        estado: insc.estado,
        motivo: insc.motivo,
        poses: insc.poses.map((p) => ({
            pose: p.pose,
            estado: p.estado,
            motivo: p.motivo,
            // La miniatura solo mientras el registro está abierto: al cerrarlo, se borra.
            miniatura: insc.abierto === true && typeof p.miniatura === "string" ? p.miniatura : null
        })),
        advertencia: insc.advertencia ? { parecido_a: insc.advertencia.parecido_a } : null,
        duplicado_de: typeof insc.duplicado_de === "string" ? insc.duplicado_de : null,
        inicio: iso(insc.inicio_ms),
        actualizado: iso(insc.actualizado_ms)
    };
}
msg.statusCode = 200;
return msg;

// DELETE /api/alumnos/:cuenta/rostro
// La cuenta sale de la ruta: 9 dígitos, o 400. Con un registro abierto de esa cuenta
// responde 409: retirar el consentimiento a media captura dejaría al registro sin
// permiso; primero se cancela. Un registro abierto de otra cuenta no estorba.
// Salida 1: sigue al UPDATE (msg.params). Salida 2: respuesta de error (400 o 409).
const cuenta = msg.req.params && msg.req.params.cuenta;

function rechazar(codigo, texto, motivo) {
    msg.statusCode = codigo;
    msg.payload = motivo === undefined ? { error: texto } : { error: texto, motivo: motivo };
    return [null, msg];
}

if (typeof cuenta !== "string" || !/^[0-9]{9}$/.test(cuenta)) {
    return rechazar(400, "cuenta debe ser de 9 dígitos");
}
const insc = flow.get("inscripcion");
if (insc && insc.abierto === true && insc.cuenta === cuenta) {
    return rechazar(409, "Hay un registro abierto de este alumno: cancélalo antes de retirar su rostro", "registro_abierto");
}
msg.params = [cuenta];
return [msg, null];

// Respuesta del UPDATE que retira el rostro: una fila {existe, tenia_rostro, actualizadas},
// leída y escrita en la misma sentencia.
//   - la cuenta no existe: 404;
//   - responde 200 con el estado nuevo, siempre "pendiente". Es idempotente: si el
//     alumno ya estaba pendiente, retirado es false y no se publica nada;
//   - si tenía rostro, publica aula/vision/galeria/baja (QoS 1, sin retención), DESPUÉS
//     de escribir en la base, para que la visión lo quite de su galería en RAM.
// Salida 1: respuesta HTTP. Salida 2: baja a la visión.
const fila = Array.isArray(msg.payload) ? msg.payload[0] : undefined;
if (!fila) {
    throw new Error("la consulta de la baja no devolvió filas");
}
const cuenta = msg.params[0];
if (fila.existe === 0) {
    msg.statusCode = 404;
    msg.payload = { error: "No existe un alumno con esa cuenta" };
    return [msg, null];
}
const teniaRostro = fila.tenia_rostro === true;
msg.statusCode = 200;
msg.payload = { cuenta: cuenta, rostro: "pendiente", retirado: teniaRostro };
if (!teniaRostro) {
    return [msg, null];
}
const baja = {
    topic: "aula/vision/galeria/baja",
    payload: JSON.stringify({ cuenta: cuenta }),
    qos: 1,
    retain: false
};
return [msg, baja];

// Progreso del registro: aula/vision/enrolamiento (QoS 0, sin retención).
// Solo actualiza la inscripción abierta, y solo si la cuenta del mensaje es la suya.
//   - esperando_pose, capturando, aceptada, rechazada: actualizan la pose del mensaje.
//   - advertencia: guarda la cuenta a la que se parece (informativa; no detiene nada).
//   - completado: la visión aceptó las 5 poses, pero la inscripción SIGUE ABIERTA hasta
//     que llegue el embedding (aula/vision/embedding, otro tópico y otra QoS: la visión
//     publica "completado" antes, pero no hay garantía de orden en la entrega). Si
//     "completado" la cerrara, el embedding que llega después se rechazaría y se
//     perdería el registro. Cierra "Tras guardar embedding".
//   - cancelado y error: cierran la inscripción y revierten el consentimiento. Un error "duplicado"
//     (el rostro ya es de otra cuenta, contrato MQTT v0.16) conserva además la cuenta dueña
//     (parecido_a, 9 dígitos) en `duplicado_de`, aparte de `advertencia`: esa se guarda igual,
//     el duplicado no.
// Cada mensaje aceptado (de este registro: ver la guarda de `ts`) renueva el plazo de 5 minutos.
// La miniatura (base64) es efímera: se guarda solo en el contexto de este flujo y solo
// mientras el registro está abierto; al cerrarlo, se borra. No va a la base de datos, no
// se registra y nunca sale por las salidas de consentimiento ni de descarte.
// Salida 1: revertir el consentimiento. Salida 2: descarte (nunca lleva el contenido).
const MAX_CARACTERES = 32768; // un mensaje con miniatura de ~8 KB pesa unos 11 KB
const MINIMIURA_MAX = 12288; // el JPEG de ~8 KB, en base64, son ~11 KB
const BASE64 = /^[A-Za-z0-9+/]+={0,2}$/;
const ESTADOS_POSE = ["esperando_pose", "capturando", "aceptada", "rechazada"];

function descartar(motivo) {
    return [null, { payload: "Descartado, " + motivo }];
}

// El progreso nunca se retiene (contrato MQTT, sección 1): un retenido sería un
// progreso falso que se repetiría en cada conexión.
// El broker de Node-RED habla MQTT 3.1.1 (protocolVersion 4): un retenido publicado en vivo llega
// con retain = false (la opción rap no existe), y solo se ve retain = true en la entrega inicial
// al (re)conectar. Este descarte aplica solo entonces, mientras no se pase a MQTT 5.
if (msg.retain === true) {
    node.warn("Descartado mensaje retenido en " + msg.topic + ": el progreso no se retiene");
    return descartar("mensaje retenido en " + msg.topic + " (el progreso no se retiene)");
}
// Payload vacío: no es un progreso. Es el mensaje en vivo que provoca la limpieza en
// cada conexión al broker.
if (msg.payload === "" || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0)) {
    return null;
}
if (typeof msg.payload !== "string") {
    return descartar("el payload no es texto");
}
if (msg.payload.length > MAX_CARACTERES) {
    return descartar("payload de " + msg.payload.length + " caracteres (máximo " + MAX_CARACTERES + ")");
}
let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (e) {
    return descartar("no es JSON");
}
if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
    return descartar("no es un objeto JSON");
}
const insc = flow.get("inscripcion");
if (!insc || insc.abierto !== true) {
    return descartar("no hay un registro abierto");
}
if (datos.cuenta !== insc.cuenta) {
    return descartar("la cuenta no coincide con el registro abierto");
}
if (typeof datos.estado !== "string") {
    return descartar("falta estado");
}

// Sesión rezagada: el mensaje debe ser de este registro. `ts` es obligatorio (contrato MQTT,
// sección 1); uno anterior al inicio (con 2 s de margen) es de una sesión pasada de la misma
// cuenta, y sin `ts` legible no hay cómo saberlo: se descarta.
const MARGEN_TS_MS = 2000;
const instante = typeof datos.ts === "string" ? Date.parse(datos.ts) : NaN;
if (Number.isNaN(instante)) {
    return descartar("falta ts o no se puede leer");
}
if (instante > Date.now() + 5 * 60 * 1000) {
    return descartar("ts posterior a la hora actual");
}
if (instante < insc.inicio_ms - MARGEN_TS_MS) {
    return descartar("el mensaje es anterior al inicio del registro");
}

// Un código del contrato (rostro_chico, ocupado...): solo minúsculas y guion bajo.
// Texto libre de la red no llega al frontend.
const motivo = (typeof datos.motivo === "string" && /^[a-z_]{1,40}$/.test(datos.motivo)) ? datos.motivo : null;
let revertir = null;

// La miniatura del contrato (JPEG en base64) se valida antes de copiarla: lo que no
// tenga forma de miniatura se ignora con un aviso (nunca con el contenido: el aviso
// solo dice el tamaño). El mensaje sigue su curso igual.
let miniatura = null;
if (datos.miniatura !== undefined && datos.miniatura !== null) {
    if (typeof datos.miniatura !== "string") {
        node.warn("Miniatura ignorada: no es un texto");
    } else if (datos.miniatura.length > MINIMIURA_MAX) {
        node.warn("Miniatura ignorada: " + datos.miniatura.length + " caracteres (máximo " + MINIMIURA_MAX + ")");
    } else if (!BASE64.test(datos.miniatura)) {
        node.warn("Miniatura ignorada: no es base64");
    } else {
        miniatura = datos.miniatura;
    }
}

if (ESTADOS_POSE.includes(datos.estado)) {
    const pose = insc.poses.find((p) => p.pose === datos.pose);
    if (!pose) {
        return descartar("pose desconocida");
    }
    pose.estado = datos.estado;
    pose.motivo = datos.estado === "rechazada" ? motivo : null;
    // La miniatura del mensaje es la de esta pose. Si el mensaje no trae una válida,
    // la pose se queda sin miniatura: no se conserva la de un intento anterior (sería
    // la foto de otra toma).
    pose.miniatura = miniatura;
    if (insc.estado === "esperando_vision") {
        insc.estado = "en_curso";
    }
} else if (datos.estado === "advertencia") {
    const parecido = (typeof datos.parecido_a === "string" && /^[0-9]{9}$/.test(datos.parecido_a)) ? datos.parecido_a : null;
    insc.advertencia = { parecido_a: parecido };
} else if (datos.estado === "completado") {
    insc.estado = "guardando";
} else if (datos.estado === "cancelado" || datos.estado === "error") {
    insc.abierto = false;
    insc.estado = datos.estado;
    insc.motivo = datos.estado === "error" ? (motivo || "desconocido") : null;
    // La cuenta dueña del rostro duplicado, con la misma validación que la advertencia; sin una
    // cuenta válida, nada (el frontend dice el motivo genérico).
    insc.duplicado_de = (insc.motivo === "duplicado" && typeof datos.parecido_a === "string" && /^[0-9]{9}$/.test(datos.parecido_a)) ? datos.parecido_a : null;
    // La miniatura no sobrevive al registro: al cerrarlo, se borra del contexto.
    for (const pose of insc.poses) {
        pose.miniatura = null;
    }
    revertir = { params: [insc.cuenta] };
} else {
    return descartar("estado desconocido");
}
insc.actualizado_ms = Date.now();
insc.ticks = 0;
flow.set("inscripcion", insc);
return [revertir, null];

// Embedding final del registro: aula/vision/embedding (QoS 1, sin retención).
// Se guarda solo si la cuenta del mensaje es la de la inscripción abierta; nunca para
// otra cuenta. La cuenta que va al UPDATE sale de la inscripción, no del mensaje.
// El consentimiento lo comprueba el propio UPDATE (AND consentimiento AND embedding IS
// NULL): este flujo nunca lo escribe a favor de nadie (plan, sección 6.4).
// Si el mensaje es de la cuenta abierta pero no sirve (dim distinta de 512, arreglo
// que no son 512 números, sin modelo), el registro termina en error y el consentimiento
// se revierte. Nunca se registra el contenido del mensaje: es un dato biométrico.
// Salida 1: UPDATE del embedding (msg.params = [texto del vector, cuenta]).
// Salida 2: descarte. Salida 3: revertir el consentimiento.
const MAX_CARACTERES = 65536; // 512 números con 4 decimales pesan unos 4 KB
const DIM = 512; // vector(512) en orangepi/sql/schema.sql

function descartar(motivo) {
    return [null, { payload: "Descartado, " + motivo }, null];
}

// El broker de Node-RED habla MQTT 3.1.1 (protocolVersion 4): un retenido publicado en vivo llega
// con retain = false (la opción rap no existe), y solo se ve retain = true en la entrega inicial
// al (re)conectar. Este descarte aplica solo entonces, mientras no se pase a MQTT 5.
if (msg.retain === true) {
    node.warn("Descartado mensaje retenido en " + msg.topic + ": el embedding no se retiene");
    return descartar("mensaje retenido en " + msg.topic + " (el embedding no se retiene)");
}
if (msg.payload === "" || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0)) {
    return null;
}
if (typeof msg.payload !== "string") {
    return descartar("el payload no es texto");
}
if (msg.payload.length > MAX_CARACTERES) {
    return descartar("payload de " + msg.payload.length + " caracteres (máximo " + MAX_CARACTERES + ")");
}
let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (e) {
    return descartar("no es JSON");
}
if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
    return descartar("no es un objeto JSON");
}
const insc = flow.get("inscripcion");
if (!insc || insc.abierto !== true) {
    return descartar("no hay un registro abierto");
}
if (datos.cuenta !== insc.cuenta) {
    return descartar("la cuenta no coincide con el registro abierto");
}

// Sesión rezagada: el mensaje debe ser de este registro. `ts` es obligatorio (contrato MQTT,
// sección 1). Un `ts` ilegible, vacío o de antes de 2000 (la visión usa 1970 como hora de reserva
// si su reloj falla) en el embedding de la cuenta abierta no se descarta en silencio: el registro
// termina en error y el consentimiento se revierte. Uno posterior a ahora + 5 min se descarta, y
// uno anterior al inicio (con 2 s de margen) es de una sesión pasada de la misma cuenta: también.
const MARGEN_TS_MS = 2000;
const TS_MINIMO_MS = Date.UTC(2000, 0, 1);
const ADELANTO_MAXIMO_MS = 5 * 60 * 1000;
const instante = typeof datos.ts === "string" ? Date.parse(datos.ts) : NaN;
if (Number.isNaN(instante) || instante < TS_MINIMO_MS) {
    return fallar("ts ilegible, vacío o de antes de 2000");
}
if (instante > Date.now() + ADELANTO_MAXIMO_MS) {
    return descartar("ts posterior a la hora actual");
}
if (instante < insc.inicio_ms - MARGEN_TS_MS) {
    return descartar("el mensaje es anterior al inicio del registro");
}

function fallar(texto) {
    insc.abierto = false;
    insc.estado = "error";
    insc.motivo = "embedding_invalido";
    // La miniatura no sobrevive al registro: al cerrarlo, se borra del contexto.
    for (const pose of insc.poses) {
        pose.miniatura = null;
    }
    insc.actualizado_ms = Date.now();
    flow.set("inscripcion", insc);
    return [null, { payload: "Descartado, " + texto }, { params: [insc.cuenta] }];
}

if (datos.dim !== DIM) {
    return fallar("dim distinto de " + DIM);
}
if (!Array.isArray(datos.embedding) || datos.embedding.length !== DIM ||
    !datos.embedding.every((x) => typeof x === "number" && Number.isFinite(x))) {
    return fallar("el embedding no es un arreglo de " + DIM + " números");
}
if (typeof datos.modelo !== "string" || datos.modelo.trim() === "") {
    return fallar("falta modelo");
}
// El contrato lo define "Normalizado L2" (sección 4, aula/vision/embedding) con 4 decimales: el
// redondeo mueve la norma menos de 0.001, así que 0.01 de tolerancia no rechaza uno bueno. Un
// vector de norma cero (o muy lejos de 1) no sirve para comparar por coseno.
const norma = Math.sqrt(datos.embedding.reduce((suma, x) => suma + x * x, 0));
if (!(Math.abs(norma - 1) <= 0.01)) {
    return fallar("el embedding no tiene norma L2 igual a 1");
}
msg.params = ["[" + datos.embedding.join(",") + "]", insc.cuenta];
msg.fuente = "embedding";
msg.inscripcion_id = insc.id; // "Tras guardar embedding" solo da de alta si sigue abierta ESTA inscripción
msg.payload = null;
return [msg, null, null];

// Respuesta del UPDATE del embedding (RETURNING no_cuenta, consentimiento_fecha): una fila si lo
// guardó, ninguna si el alumno ya no tenía consentimiento o ya tenía rostro. consentimiento_fecha
// es el texto UTC con microsegundos (to_char) del consentimiento bajo el cual quedó el embedding.
//   - guardado: cierra la inscripción como "completado" y publica aula/vision/galeria/alta
//     (QoS 1, sin retención), DESPUÉS de escribir en la base; la visión recarga entonces su
//     galería con GET /api/galeria. Si la inscripción ya se había cerrado (se canceló
//     mientras se escribía), el rostro quedó guardado de todos modos y el alta se publica:
//     la galería sigue a la base.
//   - guardado cuando la inscripción YA NO estaba abierta (se cerró como cancelado, error o
//     vencido mientras el embedding estaba en vuelo): no se da de alta. Se retira el rostro y
//     el consentimiento (esa cuenta no tenía rostro antes: si lo tuviera, no habría podido
//     abrir el registro) y "Publicar baja tras retiro tardío" avisa a la visión. El retiro va
//     condicionado a esa consentimiento_fecha: solo quita el consentimiento bajo el que se
//     guardó este embedding, nunca uno posterior. El estado de la API sigue diciendo la verdad
//     (cancelado, error...).
//   - no guardado: el registro termina en error y se revierte el consentimiento.
// Salida 1: alta a la visión. Salida 2: revertir el consentimiento. Salida 3: retirar el rostro tardío (msg.params = [cuenta, consentimiento_fecha], con fuente
// "retiro_tardio": si falla, "Cerrar y responder 500" deja el par en retiros_pendientes).
const FECHA = /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$/;
const filas = msg.payload;
const cuenta = msg.params[1];
const insc = flow.get("inscripcion");
// Solo cuenta la inscripción a la que se ligó este embedding al validarlo (`inscripcion_id`): si
// el registro R1 se canceló y R2 se abrió para la misma cuenta, el embedding de R1 que se confirma
// tarde NO es de R2 y se retira (R2 queda sin consentimiento y termina en no_guardado: falla cerrado).
const abierta = Boolean(insc) && insc.abierto === true && insc.cuenta === cuenta && insc.id === msg.inscripcion_id;

if (!Array.isArray(filas) || filas.length !== 1) {
    node.warn("Embedding rechazado por la base: sin consentimiento vigente o el alumno ya tiene rostro");
    if (!abierta) {
        return null;
    }
    insc.abierto = false;
    insc.estado = "error";
    insc.motivo = "no_guardado";
    // La miniatura no sobrevive al registro: al cerrarlo, se borra del contexto.
    for (const pose of insc.poses) {
        pose.miniatura = null;
    }
    insc.actualizado_ms = Date.now();
    flow.set("inscripcion", insc);
    return [null, { params: [cuenta] }, null];
}

if (!abierta) {
    node.warn("El embedding se guardó con el registro ya cerrado: se retira y no se da de alta");
    // Con el CHECK de la tabla, un embedding guardado siempre trae fecha. Sin ella no hay con qué
    // condicionar el retiro, y retirar a ciegas podría borrar el rostro de un registro posterior.
    const fecha = filas[0].consentimiento_fecha;
    if (typeof fecha !== "string" || !FECHA.test(fecha)) {
        throw new Error("el UPDATE del embedding no devolvió consentimiento_fecha con el formato esperado");
    }
    return [null, null, { params: [cuenta, fecha], fuente: "retiro_tardio" }];
}
insc.abierto = false;
insc.estado = "completado";
insc.motivo = null;
// La miniatura no sobrevive al registro: al cerrarlo, se borra del contexto.
for (const pose of insc.poses) {
    pose.miniatura = null;
}
insc.actualizado_ms = Date.now();
flow.set("inscripcion", insc);
const alta = {
    topic: "aula/vision/galeria/alta",
    payload: JSON.stringify({ cuenta: cuenta }),
    qos: 1,
    retain: false
};
return [alta, null, null];

// Tras el UPDATE que retira el rostro tardío ("Tras guardar embedding", o el reintento de
// "Vencer inscripción"). msg.params = [cuenta, consentimiento_fecha]; el UPDATE solo actúa si la
// fila sigue con ese consentimiento y devuelve la cuenta si actuó.
//   - 1 fila (actuó): publica aula/vision/galeria/baja (QoS 1, sin retención), después de escribir
//     en la base, para que la visión quite el rostro de su galería en RAM.
//   - 0 filas: el retiro ya había actuado antes (Node-RED murió antes de publicar la baja o de
//     quitar el par) o la fila tiene ya otro consentimiento. No se sabe cuál, y la visión pudo
//     cargar el rostro tardío: publica aula/vision/galeria/alta (QoS 1, sin retención), que le
//     hace recargar la galería completa desde la base. Queda igual que la base en los dos casos:
//     el rostro retirado desaparece y el de un registro posterior se conserva.
// En los dos casos el par sale de retiros_pendientes (almacén persistente).
const cuenta = msg.params[0];
const fecha = msg.params[1];
const pendientes = flow.get("retiros_pendientes", "persistente");
if (Array.isArray(pendientes)) {
    const resto = pendientes.filter((p) => !(p && p.cuenta === cuenta && p.fecha === fecha));
    flow.set("retiros_pendientes", resto.length > 0 ? resto : undefined, "persistente");
}
const actuo = Array.isArray(msg.payload) && msg.payload.length === 1;
node.warn(actuo
    ? "Rostro tardío retirado y baja publicada"
    : "Retiro tardío sin efecto: se publica un alta para que la visión recargue la galería");
return {
    topic: actuo ? "aula/vision/galeria/baja" : "aula/vision/galeria/alta",
    payload: JSON.stringify({ cuenta: cuenta }),
    qos: 1,
    retain: false
};

// Cada 15 s ("Cada 15 s"):
// 1. Vencimiento: si la inscripción abierta lleva 5 minutos sin progreso (cada mensaje de
//    aula/vision/enrolamiento de su cuenta renueva el plazo; plan, sección 5.4), la cierra
//    como error "vencido", ordena cancelar a la visión (por si sigue capturando) y revierte
//    el consentimiento. Con la visión apagada, es lo que cierra un registro que nadie atiende.
//    El plazo se cuenta en ticks de este temporizador (20 x 15 s) y no con Date.now(): el
//    reloj de la placa puede saltar (RTC, NTP) y un salto hacia adelante vencería un registro
//    vivo. Los temporizadores de Node.js son monotónicos y la función no tiene performance ni
//    process. Un tick tardío solo retrasa el vencimiento, nunca lo adelanta.
// 2. Reintento de la limpieza de arranque: si el UPDATE de "Al arrancar" falló (la base aún no
//    estaba lista), queda la marca `limpieza_pendiente` y se reintenta aquí, solo si no hay un
//    registro abierto (el UPDATE quitaría su consentimiento).
// 3. Reintento de los retiros tardíos que fallaron (flow.retiros_pendientes, pares cuenta/fecha
//    del consentimiento, en el almacén persistente; ver "Cerrar y responder 500"): se reenvían al
//    UPDATE de retiro, que solo actúa sobre esa fecha; la baja se publica cuando sale bien y
//    actuó ("Publicar baja tras retiro tardío"). Una cuenta con un registro abierto no se
//    reintenta. Una entrada con otra forma (cuenta suelta, fecha ilegible) se ignora.
// Salida 1: orden a aula/vision/cmd. Salida 2: revertir el consentimiento.
// Salida 3: limpieza de arranque. Salida 4: retiros tardíos (uno por cuenta pendiente).
const TICKS_PARA_VENCER = 20;
const insc = flow.get("inscripcion");
const abierta = Boolean(insc) && insc.abierto === true;

let limpieza = null;
if (flow.get("limpieza_pendiente") === true && !abierta) {
    node.log("Se reintenta la limpieza de arranque");
    limpieza = { payload: null };
}
const pendientes = flow.get("retiros_pendientes", "persistente");
const FECHA = /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$/;
const retiros = Array.isArray(pendientes)
    ? pendientes
        .filter((p) => p && /^[0-9]{9}$/.test(String(p.cuenta)) && typeof p.fecha === "string" && FECHA.test(p.fecha))
        .filter((p) => !(abierta && insc.cuenta === p.cuenta))
        .map((p) => ({ params: [p.cuenta, p.fecha], fuente: "retiro_tardio" }))
    : [];
if (retiros.length > 0) {
    node.log("Se reintenta el retiro de " + retiros.length + " rostro(s) tardío(s)");
}
const adicionales = [limpieza, retiros.length > 0 ? retiros : null];

if (!abierta) {
    return (limpieza === null && retiros.length === 0) ? null : [null, null, ...adicionales];
}
insc.ticks = (Number.isInteger(insc.ticks) ? insc.ticks : 0) + 1;
if (insc.ticks < TICKS_PARA_VENCER) {
    flow.set("inscripcion", insc);
    return retiros.length === 0 ? null : [null, null, null, retiros];
}
insc.abierto = false;
insc.apartada = false;
insc.estado = "error";
insc.motivo = "vencido";
// La miniatura no sobrevive al registro: al cerrarlo, se borra del contexto.
for (const pose of insc.poses) {
    pose.miniatura = null;
}
insc.actualizado_ms = Date.now();
flow.set("inscripcion", insc);
node.warn("Registro vencido: 5 minutos sin progreso");
const orden = {
    topic: "aula/vision/cmd",
    payload: JSON.stringify({ accion: "cancelar", cuenta: insc.cuenta }),
    qos: 1,
    retain: false
};
return [orden, { params: [insc.cuenta] }, null, retiros.length === 0 ? null : retiros];

// Al arrancar Node-RED o desplegar los flujos (plan, sección 5.4, paso 10): las
// inscripciones viven en memoria y no sobreviven. Primero se borra la inscripción del
// contexto; el nodo siguiente ejecuta el UPDATE que quita los consentimientos que
// quedaron sin rostro. Un registro que la visión siga atendiendo termina con un
// embedding que ya no se acepta (no hay inscripción abierta).
// La marca `limpieza_pendiente` queda puesta hasta que el UPDATE tenga éxito
// ("Limpieza de arranque lista"): si falla (la base aún no estaba lista), "Vencer
// inscripción" lo reintenta cada 15 s.
flow.set("inscripcion", undefined);
flow.set("limpieza_pendiente", true);
node.log("Arranque: se borran las inscripciones pendientes y los consentimientos sin rostro");
msg.payload = null;
return msg;

// El UPDATE de limpieza de arranque tuvo éxito: ya no hace falta reintentarlo.
flow.set("limpieza_pendiente", undefined);
return null;

// Respuesta del UPDATE que revierte el consentimiento. Solo POST /api/enrolamiento/cancelar
// trae msg.req y espera respuesta; las demás rutas (progreso, embedding, vencimiento,
// fallos) mandan un mensaje nuevo y terminan aquí sin responder.
if (!msg.req) {
    return null;
}
msg.statusCode = 200;
msg.payload = { cancelado: true, abierto: false };
return msg;

// Error de ejecución (la base, sobre todo) en cualquier ruta de este flujo.
// Se registra solo el código SQLSTATE (cinco caracteres), o un mensaje truncado y sin
// secuencias de 9 dígitos: nunca msg ni msg.params (traen embeddings y cuentas), el
// detalle de Postgres, el mensaje completo ni la ruta con la cuenta (se registra la
// plantilla de la ruta, /api/alumnos/:cuenta/rostro).
// Además:
//   - si la petición había apartado el lugar de la inscripción y no llegó a abrirla, lo libera;
//   - si falla el UPDATE del embedding, el registro termina en error y se revierte el
//     consentimiento (si esa reversión falla también, solo se registra);
//   - si falla el retiro de un rostro tardío (fuente "retiro_tardio"), el par cuenta/fecha del
//     consentimiento queda en flow.retiros_pendientes (almacén "persistente": sobrevive a un
//     reinicio) y "Vencer inscripción" lo reintenta cada 15 s hasta que salga.
// Se responde 500 si el mensaje viene de una petición HTTP (trae msg.req).
// Salida 1: respuesta HTTP. Salida 2: revertir el consentimiento.
const error = msg.error || {};
let causa;
if (typeof error.code === "string" && /^[0-9A-Z]{5}$/.test(error.code)) {
    causa = "SQLSTATE " + error.code;
} else if (typeof error.message === "string" && error.message !== "") {
    causa = error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120);
} else {
    causa = "error desconocido";
}
let ruta = "";
if (msg.req) {
    const plantilla = msg.req.route && typeof msg.req.route.path === "string" ? msg.req.route.path : "(ruta)";
    ruta = msg.req.method + " " + plantilla.replace(/[0-9]{9}/g, "*********") + " ";
}
node.warn("Registro: " + ruta + "falló: " + causa);

if (msg.reserva) {
    const i = flow.get("inscripcion");
    if (i && i.id === msg.reserva && i.apartada === true) {
        flow.set("inscripcion", undefined);
    }
}
let revertir = null;
if (msg.fuente === "retiro_tardio" && Array.isArray(msg.params) && /^[0-9]{9}$/.test(String(msg.params[0])) &&
    typeof msg.params[1] === "string" && /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$/.test(msg.params[1])) {
    const guardados = flow.get("retiros_pendientes", "persistente");
    const pendientes = Array.isArray(guardados) ? guardados : [];
    if (!pendientes.some((p) => p && p.cuenta === msg.params[0] && p.fecha === msg.params[1])) {
        pendientes.push({ cuenta: msg.params[0], fecha: msg.params[1] });
    }
    flow.set("retiros_pendientes", pendientes, "persistente");
}
if (msg.fuente === "embedding") {
    const insc = flow.get("inscripcion");
    if (insc && insc.abierto === true && Array.isArray(msg.params) && insc.cuenta === msg.params[1] && insc.id === msg.inscripcion_id) {
        insc.abierto = false;
        insc.estado = "error";
        insc.motivo = "no_guardado";
        // La miniatura no sobrevive al registro: al cerrarlo, se borra del contexto.
        for (const pose of insc.poses) {
            pose.miniatura = null;
        }
        insc.actualizado_ms = Date.now();
        flow.set("inscripcion", insc);
        revertir = { params: [insc.cuenta] };
    }
}
let respuesta = null;
if (msg.req) {
    msg.statusCode = 500;
    msg.payload = { error: "No se pudo completar la operación en la base de datos" };
    respuesta = msg;
}
return [respuesta, revertir];

// Error al leer el estado del registro (GET, solo lectura): se registra el mensaje
// truncado, sin secuencias de 9 dígitos, y se responde 500.
const error = msg.error || {};
const causa = (typeof error.message === "string" && error.message !== "")
    ? error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120)
    : "error desconocido";
node.warn("GET /api/enrolamiento/estado falló: " + causa);
msg.statusCode = 500;
msg.payload = { error: "No se pudo leer el estado del registro" };
return msg;

// Orden de sesión: aula/sesion/cmd (QoS 1, sin retención). La publica la pantalla (contrato MQTT,
// sección 5):
//   {"accion":"iniciar","materia":"FSE","grupo":"1","tol_min":10}   |   {"accion":"terminar"}
// `marcar` es solo una propuesta del contrato y no está implementada: se descarta con un aviso.
// Salida 1: iniciar (msg.params = [materia, grupo, tol_min], ya validados).
// Salida 2: terminar. Salida 3: descarte.
// Un descarte o un aviso nunca repite el contenido del mensaje.
// Límite (CWE-770): un `iniciar` es una escritura en la base y, si cierra una sesión olvidada, un
// reporte con un proceso de Python. Se descarta un `iniciar` válido que llegue a menos de 5 s del
// último aceptado; eso cubre también la reentrega duplicada de un QoS 1. El instante vive en el
// contexto en memoria (`ultimo_iniciar_ms`). Limitación: se mide con Date.now(), que puede saltar
// (RTC, NTP) y la función no tiene performance ni process (el vencimiento del registro lo resuelve
// con ticks de un temporizador). Por eso solo se descarta si pasaron entre 0 y 5 s: un reloj que
// salta hacia atrás o adelante acepta en vez de bloquear. Los descartados no renuevan la ventana.
const MAX_CARACTERES = 1024;
const MAX_MATERIA = 40;
const MAX_GRUPO = 40; // el mismo tope que el grupo de la importación de alumnos
const MAX_TOL_MIN = 600; // como valida la pantalla (orangepi/pantalla/estado.py)
const MIN_ENTRE_INICIOS_MS = 5000; // la pantalla ya pide doble toque para iniciar
// aula/sesion/estado se lee en la XIAO con PubSubClient, de búfer 256 (contrato MQTT, sección 1): 3
// bytes de cabecera fija, 2 de longitud del tópico, 18 del tópico y 2 del id de paquete dejan 231
// para el payload; 220 deja margen. Se comprueba con el peor caso (id de 10 dígitos): un iniciar
// cuyo estado no cabría se descarta, en vez de dejar a la XIAO sin enterarse de la sesión.
const MAX_ESTADO_BYTES = 220;
// Caracteres de control (\n incluido), invisibles de formato (ancho cero, inversión de texto...) y
// separadores de línea y de párrafo.
const CONTROL = /[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u;

function descartar(motivo) {
    return [null, null, { payload: "Descartado, " + motivo }];
}

// Texto no vacío, en NFC y sin espacios en los extremos. Devuelve { valor } o { error }.
function texto(valor, campo, max) {
    if (typeof valor !== "string") {
        return { error: campo + " debe ser texto" };
    }
    const t = valor.normalize("NFC").trim();
    if (t === "") {
        return { error: campo + " vacío" };
    }
    if ([...t].length > max) {
        return { error: campo + " de más de " + max + " caracteres" };
    }
    if (CONTROL.test(t)) {
        return { error: campo + " con caracteres de control o invisibles" };
    }
    return { valor: t };
}

// Las órdenes nunca se retienen (contrato MQTT, sección 1): un retenido se volvería a ejecutar en
// cada conexión. El broker de Node-RED habla MQTT 3.1.1 (protocolVersion 4): un retenido publicado
// en vivo llega con retain = false, y solo se ve retain = true en la entrega inicial al
// (re)conectar. Este descarte aplica solo entonces, mientras no se pase a MQTT 5. Además, la
// limpieza de retenidos borra el de este tópico en cada conexión.
if (msg.retain === true) {
    node.warn("Descartado mensaje retenido en " + msg.topic + ": una orden de sesión no se retiene");
    return descartar("mensaje retenido en " + msg.topic + " (una orden no se retiene)");
}
// Payload vacío: no es una orden. Es el mensaje en vivo que provoca la limpieza de retenidos en
// cada conexión al broker.
if (msg.payload === "" || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0)) {
    return null;
}
if (typeof msg.payload !== "string") {
    return descartar("el payload no es texto");
}
if (msg.payload.length > MAX_CARACTERES) {
    return descartar("payload de " + msg.payload.length + " caracteres (máximo " + MAX_CARACTERES + ")");
}
let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (e) {
    return descartar("no es JSON");
}
if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
    return descartar("no es un objeto JSON");
}

if (datos.accion === "terminar") {
    return [null, { fuente: "terminar", payload: null }, null];
}
if (datos.accion === "marcar") {
    node.warn("Descartado: la acción marcar no está implementada (es una propuesta del contrato)");
    return descartar("la acción marcar no está implementada");
}
if (datos.accion !== "iniciar") {
    return descartar("accion debe ser iniciar o terminar");
}

const materia = texto(datos.materia, "materia", MAX_MATERIA);
if (materia.error) {
    return descartar(materia.error);
}
const grupo = texto(datos.grupo, "grupo", MAX_GRUPO);
if (grupo.error) {
    return descartar(grupo.error);
}
if (!Number.isInteger(datos.tol_min) || datos.tol_min < 0 || datos.tol_min > MAX_TOL_MIN) {
    return descartar("tol_min debe ser un entero de 0 a " + MAX_TOL_MIN);
}
const peor = {
    activa: true, id: 2147483647, materia: materia.valor, grupo: grupo.valor,
    inicio: "2026-11-05T15:30:12+00:00", tol_min: datos.tol_min
};
if (Buffer.byteLength(JSON.stringify(peor), "utf8") > MAX_ESTADO_BYTES) {
    return descartar("el estado de la sesión no cabría en el búfer de la XIAO (materia y grupo muy largos)");
}
const ahora = Date.now();
const ultimo = flow.get("ultimo_iniciar_ms");
if (Number.isFinite(ultimo) && ahora - ultimo >= 0 && ahora - ultimo < MIN_ENTRE_INICIOS_MS) {
    node.warn("Descartado: un iniciar llegó a menos de 5 s del anterior");
    return descartar("iniciar demasiado seguido (menos de 5 s desde el último aceptado)");
}
flow.set("ultimo_iniciar_ms", ahora);
return [{ fuente: "iniciar", params: [materia.valor, grupo.valor, datos.tol_min], payload: null }, null, null];

// Respuesta del CTE de iniciar (una fila): la sesión nueva, el total de alumnos del grupo en
// `faltantes` y, si había una abierta olvidada, su id en `cerrada_id`. Se publica DESPUÉS de
// escribir en la base: los retenidos nunca adelantan a la base.
// Si la respuesta no es lo esperado, lanza: el catch reconcilia y publica lo que diga la base.
// Salida 1: aula/sesion/estado. Salida 2: reporte de la olvidada. Salida 3: aula/sesion/asistencia.
const filas = msg.payload;
if (!Array.isArray(filas) || filas.length !== 1) {
    throw new Error("el INSERT de la sesión no devolvió una fila");
}
const f = filas[0];
if (!Number.isSafeInteger(f.id) || f.id < 1) {
    throw new Error("el INSERT de la sesión no devolvió un id válido");
}
if (!Number.isSafeInteger(f.faltantes) || f.faltantes < 0) {
    throw new Error("el INSERT de la sesión no devolvió faltantes válidos");
}
const estado = {
    activa: true,
    id: f.id,
    materia: f.materia,
    grupo: f.grupo,
    inicio: f.inicio,
    tol_min: f.tol_min
};
const asistencia = {
    activa: true,
    id: f.id,
    presentes: 0,
    retardos: 0,
    faltantes: f.faltantes,
    ultimo: null
};
// Las miniaturas del pase de lista son de la sesión que se cerró (o de ninguna): al iniciar otra se borran.
global.set("miniaturas_pase", undefined);
if (Number.isSafeInteger(f.cerrada_id) && f.cerrada_id >= 1) {
    // Que un resultado rezagado de la sesión olvidada que se cerró no vuelva a crear su almacén.
    const previa = global.get("miniaturas_pase_cerrada");
    global.set("miniaturas_pase_cerrada", Number.isSafeInteger(previa) && previa > f.cerrada_id ? previa : f.cerrada_id);
}
node.log("Sesión " + f.id + " iniciada");
let reporte = null;
if (f.cerrada_id !== null && f.cerrada_id !== undefined) {
    node.log("Iniciar cerró la sesión olvidada " + f.cerrada_id + ": se genera su reporte");
    reporte = { sesion_id: f.cerrada_id };
}
return [{ payload: JSON.stringify(estado) }, reporte, { payload: JSON.stringify(asistencia) }];

// Respuesta de "UPDATE cerrar sesión" (RETURNING id): una fila si había una sesión abierta, ninguna
// si no. Se publica DESPUÉS de escribir en la base.
//   - Con sesión: publica {"activa":false,"id":N} en aula/sesion/estado, {"activa":false} en
//     aula/sesion/asistencia y pide el reporte.
//   - Sin sesión: no cambia nada en la base, no hay reporte y no se publica un estado inventado:
//     se pide el estado real a la base (mismo SELECT de la reconciliación), que corrige retenidos
//     viejos si los hubiera.
// Salida 1: aula/sesion/estado. Salida 2: reporte. Salida 3: reconciliar. Salida 4: aula/sesion/asistencia.
const filas = msg.payload;
if (!Array.isArray(filas) || filas.length > 1) {
    throw new Error("el UPDATE de cerrar la sesión no devolvió 0 o 1 filas");
}
if (filas.length === 0) {
    node.log("Terminar sin sesión abierta: no cambia nada; se republica el estado real de la base");
    return [null, null, { fuente: "reconciliar", payload: null }, null];
}
const id = filas[0].id;
if (!Number.isSafeInteger(id) || id < 1) {
    throw new Error("el UPDATE de cerrar la sesión no devolvió un id válido");
}
// Al cerrar la sesión se borran las miniaturas del pase de lista (viven solo mientras está abierta).
// `miniaturas_pase_cerrada` recuerda el id cerrado: un `presente` en vuelo de esa sesión no vuelve a guardar fotos.
global.set("miniaturas_pase", undefined);
const previa = global.get("miniaturas_pase_cerrada");
global.set("miniaturas_pase_cerrada", Number.isSafeInteger(previa) && previa > id ? previa : id);
node.log("Sesión " + id + " terminada");
return [{ payload: JSON.stringify({ activa: false, id: id }) }, { sesion_id: id }, null, { payload: JSON.stringify({ activa: false }) }];

// Llega el estado del nodo "Publicar estado de sesión". Solo interesa "conectado" (verde, punto):
// es el estado que mqtt out emite cuando ya puede publicar, al arrancar, al desplegar y al
// reconectar (también tras reiniciar Mosquitto). Entonces se reconcilian aula/sesion/estado y
// aula/sesion/asistencia con la base: se publica la sesión abierta o el estado inactivo, para que
// la XIAO y la pantalla vean la verdad aunque el broker haya perdido el retenido.
// `reconciliar_pendiente` queda puesta hasta que "Estado de la base" publique: si la consulta
// falla (la base no responde), "Reintentar reconciliación" la repite cada 15 s.
const s = msg.status || {};
if (s.fill !== "green" || s.shape !== "dot") {
    return null;
}
flow.set("reconciliar_pendiente", true);
node.log("Conectado al broker: se reconcilia aula/sesion/estado con la base");
return { fuente: "reconciliar", payload: null };

// Respuesta de "SELECT sesión actual": a lo más una fila, la sesión abierta o, si no hay, la
// última cerrada. Publica lo que dice la base (contrato MQTT, sección 5):
//   - salida 1 (aula/sesion/estado): {"activa":true,...} o {"activa":false,"id":<última>} o {"activa":false}
//   - salida 2 (aula/sesion/asistencia): {"activa":true,"id","presentes","retardos","faltantes","ultimo"} o {"activa":false}
// Quita la marca `reconciliar_pendiente` solo al publicar; si la respuesta es imposible, lanza y
// la marca queda para el reintento.
const filas = msg.payload;
if (!Array.isArray(filas) || filas.length > 1) {
    throw new Error("la consulta de la sesión actual no devolvió 0 o 1 filas");
}
let estado = { activa: false };
let asistencia = { activa: false };
if (filas.length === 1) {
    const f = filas[0];
    if (!Number.isSafeInteger(f.id) || f.id < 1) {
        throw new Error("la consulta de la sesión actual no devolvió un id válido");
    }
    if (f.abierta === true) {
        if (!Number.isSafeInteger(f.presentes) || f.presentes < 0
            || !Number.isSafeInteger(f.retardos) || f.retardos < 0
            || !Number.isSafeInteger(f.faltantes) || f.faltantes < 0) {
            throw new Error("la consulta de la sesión actual no devolvió conteos válidos");
        }
        let ultimo = null;
        const nom = f.ultimo_nombre;
        const est = f.ultimo_estado;
        if (nom !== null && nom !== undefined) {
            if (typeof nom !== "string" || nom === "" || (est !== "presente" && est !== "retardo")) {
                throw new Error("la consulta de la sesión actual no devolvió un último registro válido");
            }
            ultimo = { nombre: nom, estado: est };
        } else if (est !== null && est !== undefined) {
            throw new Error("la consulta de la sesión actual devolvió estado sin alumno");
        }
        estado = { activa: true, id: f.id, materia: f.materia, grupo: f.grupo, inicio: f.inicio, tol_min: f.tol_min };
        asistencia = { activa: true, id: f.id, presentes: f.presentes, retardos: f.retardos, faltantes: f.faltantes, ultimo: ultimo };
    } else {
        estado = { activa: false, id: f.id };
    }
}
// Si la base dice que no hay sesión abierta y devuelve la última cerrada (cerrada por otro camino: un superusuario, o un
// cierre que esta pestaña no vio), las miniaturas del pase de lista de esa sesión o de una anterior ya no tienen sesión:
// se borran y se recuerda el id cerrado. Esta respuesta puede llegar tarde (la consulta corrió antes de un `iniciar`):
// si el almacén es de una sesión POSTERIOR a la cerrada que devolvió la base, es de una sesión recién abierta y no se toca.
// Sin ninguna fila no hay con qué comparar el almacén (una consulta rezagada podría borrar el de la primera sesión): no se
// borra; el almacén de una sesión que no existe en la base no lo sirve la API (exige sesión abierta con ese id).
if (!estado.activa && filas.length === 1) {
    const almacen = global.get("miniaturas_pase");
    if (!(almacen && typeof almacen === "object" && almacen.sesion_id > filas[0].id)) {
        global.set("miniaturas_pase", undefined);
    }
    const previa = global.get("miniaturas_pase_cerrada");
    global.set("miniaturas_pase_cerrada", Number.isSafeInteger(previa) && previa > filas[0].id ? previa : filas[0].id);
}
flow.set("reconciliar_pendiente", undefined);
node.log("Estado de la sesión reconciliado con la base: " + (estado.activa ? "activa " + estado.id : "inactiva"));
return [{ payload: JSON.stringify(estado) }, { payload: JSON.stringify(asistencia) }];

// Cada 15 s: si la reconciliación de aula/sesion/estado quedó pendiente (la consulta falló), la repite.
if (flow.get("reconciliar_pendiente") !== true) {
    return null;
}
node.log("Se reintenta reconciliar aula/sesion/estado con la base");
return { fuente: "reconciliar", payload: null };

// Pide el reporte de una sesión que se cerró. `sesion_id` lo puso una función de este flujo a
// partir de lo que devolvió la base (nunca de un mensaje MQTT); aquí se vuelve a comprobar que sea
// un entero positivo del tamaño de un INT, porque acabará en la línea de comandos del nodo exec.
// Salida: msg.params = [id] para "SELECT reporte de asistencia" (plan, sección 7.3), que antes pasa
// por "Cola de reportes": a lo más 1 mensaje cada 2 s, para que nunca haya dos python3 a la vez. Lo
// que espera en la cola es solo el id y los parámetros, sin filas ni nombres.
const id = msg.sesion_id;
if (!Number.isSafeInteger(id) || id < 1 || id > 2147483647) {
    throw new Error("id de sesión inválido para el reporte");
}
return { sesion_id: id, params: [id], payload: null };

// Filas del reporte (plan, sección 7.3): no_cuenta, nombre, estado (presente, retardo o falta) y
// hora de la asistencia en hora de la Ciudad de México (o null en las faltas). Las filas pasan al
// programa de Python por un archivo y no por la línea de comandos: el nodo "file" escribe el JSON
// en /data/reportes/.entrada-<id>.json (ruta fija; el id es el entero ya validado) y el programa lo
// lee, lo valida otra vez y escribe sesion-<id>.csv. Se copian solo los cuatro campos.
// Un grupo sin alumnos da cero filas: el CSV queda con el encabezado.
const MAX_FILAS = 1000;
const id = msg.sesion_id;
if (!Number.isSafeInteger(id) || id < 1 || id > 2147483647) {
    throw new Error("id de sesión inválido para el reporte");
}
if (!Array.isArray(msg.payload)) {
    throw new Error("la consulta del reporte no devolvió un arreglo");
}
if (msg.payload.length > MAX_FILAS) {
    throw new Error("la consulta del reporte devolvió más de " + MAX_FILAS + " filas");
}
const filas = msg.payload.map((f) => ({
    no_cuenta: f.no_cuenta,
    nombre: f.nombre,
    estado: f.estado,
    hora: f.hora === undefined ? null : f.hora
}));
msg.payload = JSON.stringify({ sesion: id, filas: filas });
msg.filename = "/data/reportes/.entrada-" + id + ".json";
return msg;

// Último paso antes del nodo exec, que añade msg.payload a su comando fijo
// (/usr/bin/python3 -I -B /etc/nodered/reporte_csv.py <payload>, sin shell). Aquí el payload deja de
// ser el JSON de las filas y pasa a ser solo el id entero de la sesión, el que devolvió la base:
// ningún dato de MQTT ni de HTTP llega a la línea de comandos. Si el id no es un entero positivo
// del tamaño de un INT, lanza y el exec no corre.
const id = msg.sesion_id;
if (!Number.isSafeInteger(id) || id < 1 || id > 2147483647) {
    throw new Error("id de sesión inválido para el comando del reporte");
}
msg.payload = String(id);
return msg;

// Tercera salida del nodo exec: msg.payload.code es el código de salida del programa (0 = bien).
// Solo se registra el id y el código: el programa no imprime datos de alumnos, y aquí tampoco se
// copia nada de las filas.
const r = (msg.payload !== null && typeof msg.payload === "object") ? msg.payload : {};
const id = msg.sesion_id;
if (r.code === 0) {
    node.log("Reporte de la sesión " + id + " escrito en /data/reportes/sesion-" + id + ".csv");
    return null;
}
const codigo = Number.isInteger(r.code) ? String(r.code) : "desconocido";
const senal = (typeof r.signal === "string" && /^SIG[A-Z0-9]{1,10}$/.test(r.signal)) ? " (señal " + r.signal + ")" : "";
node.warn("Reporte de la sesión " + id + " falló: código " + codigo + senal);
return null;

// Error de ejecución (la base, sobre todo) en cualquier nodo de este flujo. Se registra solo el
// código SQLSTATE (cinco caracteres), o un mensaje truncado y sin secuencias de 9 dígitos: nunca
// msg ni msg.params (traen la materia, el grupo y las filas con nombres de alumnos).
//   - Falla iniciar o terminar (`fuente`): no se publica nada. Se reconcilia: el SELECT lleva al
//     broker lo que dice la base, de modo que una carrera que viole sesiones_una_abierta_idx
//     (23505) o un fallo a medias nunca deja un estado falso retenido.
//   - Falla la reconciliación: queda `reconciliar_pendiente` y se reintenta cada 15 s. No vuelve
//     a reconciliar por su cuenta (sería un bucle si la base está caída).
//   - Falla el reporte: solo se registra; la sesión ya quedó cerrada y publicada.
// Salida: pide la reconciliación.
const error = msg.error || {};
let causa;
if (typeof error.code === "string" && /^[0-9A-Z]{5}$/.test(error.code)) {
    causa = "SQLSTATE " + error.code;
} else if (typeof error.message === "string" && error.message !== "") {
    causa = error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120);
} else {
    causa = "error desconocido";
}
const que = msg.fuente === "iniciar" || msg.fuente === "terminar" || msg.fuente === "reconciliar"
    ? msg.fuente
    : (msg.sesion_id !== undefined ? "reporte" : "operación");
node.warn("Sesiones: " + que + " falló: " + causa);
if (msg.fuente === "reconciliar") {
    flow.set("reconciliar_pendiente", true);
    return null;
}
if (msg.fuente === "iniciar" || msg.fuente === "terminar") {
    return { fuente: "reconciliar", payload: null };
}
return null;

// Resultado de la visión: aula/vision/resultado (QoS 1, sin retención; contrato MQTT, sección 4).
//   {"ts":"…","modo":"pase","decision":"reconocido","cuenta":"320068234","conf":0.78,"margen":0.21,"lat_ms":{…}}
// Solo `modo: "pase"` llega a la base. `modo: "prueba"` (la prueba inmediata del registro) no marca asistencia
// ni manda retroalimentación: sale por la salida 4 hacia la pestaña Registro (GET /api/enrolamiento/prueba).
// Salida 1: reconocido, dudoso, desconocido o imagen_insuficiente → la sentencia de Postgres, con
//           msg.params = [decision, cuenta, conf] ya validados.
// Salida 2: avisos y descartes (nodo debug de consola). Nunca repiten el contenido del mensaje: la
//           cuenta y el nombre de un alumno no deben quedar en el log.
// Salida 3: la latencia de inferencia (`lat_ms`) de todo resultado que pasó esta validación, sea cual sea
//           el modo y la decisión y haya o no sesión abierta: mide la inferencia, no la asistencia. Va
//           aparte, por su propio límite y su propia inserción, y sale después de la asistencia: no la
//           cambia ni la retrasa. Copia solo las cuatro etapas, sin la cuenta ni nada más del mensaje.
// Salida 4: solo el resultado de `modo: "prueba"`, ya validado ({decision, cuenta, conf, margen, motivo, lat_ms, ts_ms}, con
//           `motivo` solo si es un código de minúsculas y guion bajo y `ts_ms` el `ts` en ms), por un enlace hacia
//           "Guardar resultado de la prueba" (pestaña Registro). Es el único camino de la cuenta fuera de esta función
//           (nunca llega a los avisos ni al log); el aviso de la salida 2 sigue sin cuenta.
// Miniatura (contrato MQTT v0.17): solo el `reconocido` de `modo: "pase"` puede traer `miniatura` (JPEG en base64, de
//           ~8 KB como máximo). Si es válida, se copia a `msg.miniatura` de la salida 1, que la lleva hasta
//           "Retroalimentación del pase" (ahí se guarda solo en memoria si el resultado es presente o retardo). En cualquier
//           otro modo o decisión se ignora sin copiarla. Una inválida se ignora con un aviso (solo su tamaño, nunca su
//           contenido, y a lo más uno cada 10 s): no descarta el resultado ni impide registrar la asistencia. Ninguna salida
//           de avisos la lleva. Válida = base64 con relleno (largo múltiplo de 4), de un JPEG (empieza con "/9j/") y de hasta
//           12 288 caracteres.
// `sin_rostro` y `error` no llevan retroalimentación (casi siempre fue un disparo del PIR sin nadie
// enfrente): solo dejan un aviso.
// Un resultado real pesa unos 250 bytes; con la miniatura (el JPEG de ~8 KB son 10 924 caracteres en base64, y el
// tope de la miniatura es 12 288) pesa unos 11 KB. 16 384 = 12 288 de la miniatura + unos 4 KB para el resto del
// mensaje (que real es de 250 bytes): deja margen sin aceptar payloads de decenas de KB antes del límite de 5 por segundo.
const MAX_CARACTERES = 16384;
const MINIATURA_MAX = 12288;
const BASE64 = /^[A-Za-z0-9+/]+={0,2}$/;
const JPEG_BASE64 = "/9j/"; // FF D8 FF en base64: el principio de todo JPEG
const AVISO_MINIATURA_CADA_MS = 10 * 1000;
const VENTANA_TS_MS = 60 * 1000;
const DECISIONES = ["reconocido", "dudoso", "desconocido", "sin_rostro", "imagen_insuficiente", "error"];
const CUENTA = /^[0-9]{9}$/;
// ISO 8601 con zona, como la estampa la visión: "2026-11-04T09:12:33.120-06:00" (también "Z").
const TS = /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$/;

function descartar(motivo) {
    return [null, { payload: "Descartado, " + motivo }];
}

// Los avisos de miniatura inválida salen antes del límite de 5 por segundo: se limitan a uno cada 10 s (con la cuenta de
// los suprimidos) para que un goteo de miniaturas malas no inunde el log. El contador vive en el contexto del nodo.
// Como el límite de `iniciar`, solo suprime si pasaron entre 0 y 10 s: un reloj que salta no bloquea el aviso.
function avisarMiniatura(texto) {
    const ahora = Date.now();
    const estado = context.get("aviso_miniatura") || { ultimo: null, suprimidos: 0 };
    if (estado.ultimo !== null && ahora - estado.ultimo >= 0 && ahora - estado.ultimo < AVISO_MINIATURA_CADA_MS) {
        estado.suprimidos += 1;
        context.set("aviso_miniatura", estado);
        return;
    }
    node.warn(texto + (estado.suprimidos > 0 ? " (" + estado.suprimidos + " avisos de miniatura suprimidos)" : ""));
    context.set("aviso_miniatura", { ultimo: ahora, suprimidos: 0 });
}

// Un resultado nunca se retiene (contrato MQTT, sección 1): un retenido repetiría en cada conexión un
// reconocimiento que ya pasó. El broker de Node-RED habla MQTT 3.1.1 (protocolVersion 4): un retenido
// publicado en vivo llega con retain = false, y solo se ve retain = true en la entrega inicial al
// (re)conectar. Este descarte aplica solo entonces, mientras no se pase a MQTT 5; lo que sí cubre
// siempre es la ventana de `ts` de abajo.
if (msg.retain === true) {
    node.warn("Descartado mensaje retenido en " + msg.topic + ": un resultado no se retiene");
    return descartar("mensaje retenido en " + msg.topic + " (un resultado no se retiene)");
}
// Payload vacío: no es un resultado.
if (msg.payload === "" || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0)) {
    return null;
}
if (typeof msg.payload !== "string") {
    return descartar("el payload no es texto");
}
if (msg.payload.length > MAX_CARACTERES) {
    return descartar("payload de " + msg.payload.length + " caracteres (máximo " + MAX_CARACTERES + ")");
}
let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (e) {
    return descartar("no es JSON");
}
if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
    return descartar("no es un objeto JSON");
}

if (datos.modo !== "pase" && datos.modo !== "prueba") {
    return descartar("modo debe ser pase o prueba");
}
if (typeof datos.decision !== "string" || !DECISIONES.includes(datos.decision)) {
    return descartar("decision desconocida");
}
// `cuenta` y `conf` son obligatorios en el contrato, pero llevan null cuando no hubo candidato.
if (datos.cuenta !== null && (typeof datos.cuenta !== "string" || !CUENTA.test(datos.cuenta))) {
    return descartar("cuenta debe ser null o un texto de 9 dígitos");
}
// La similitud coseno de un candidato sin parecido puede ser negativa: el contrato dice 0 a 1, pero
// aquí se acepta de -1 a 1 para no perder un intento por un decimal de más.
if (datos.conf !== null && (typeof datos.conf !== "number" || !Number.isFinite(datos.conf) || datos.conf < -1 || datos.conf > 1)) {
    return descartar("conf debe ser null o un número de -1 a 1");
}
if (datos.margen !== undefined && datos.margen !== null && (typeof datos.margen !== "number" || !Number.isFinite(datos.margen))) {
    return descartar("margen debe ser null o un número");
}
if (datos.lat_ms === null || typeof datos.lat_ms !== "object" || Array.isArray(datos.lat_ms)) {
    return descartar("lat_ms debe ser un objeto");
}
if (datos.decision === "reconocido" && (datos.cuenta === null || datos.conf === null)) {
    return descartar("un reconocido exige cuenta y conf");
}

// Mensaje vencido: `ts` es obligatorio y debe estar a menos de 60 s del reloj de Node-RED, hacia
// atrás o hacia adelante. Así cae un retenido viejo, una reentrega tardía y el 1970 de reserva que
// usa la visión cuando no tiene hora (contrato MQTT, sección 4). El reloj de la placa y el de la
// visión son el mismo (la RTC); un reloj mal puesto descarta los reconocimientos con aviso.
if (typeof datos.ts !== "string" || !TS.test(datos.ts)) {
    return descartar("falta ts o no es ISO 8601 con zona");
}
const instante = Date.parse(datos.ts);
if (Number.isNaN(instante)) {
    return descartar("ts no se puede leer");
}
if (Math.abs(Date.now() - instante) > VENTANA_TS_MS) {
    return descartar("ts a más de 60 s del reloj de Node-RED");
}

// Desde aquí el resultado es válido: su latencia se guarda aunque la asistencia lo ignore. Sus valores se
// validan en "Preparar latencia de la NPU"; uno malo no descarta el resultado ni cambia la asistencia.
const latencia = { payload: null, lat_ms: { cap: datos.lat_ms.cap, det: datos.lat_ms.det, emb: datos.lat_ms.emb, total: datos.lat_ms.total } };

if (datos.modo === "prueba") {
    const motivo = (typeof datos.motivo === "string" && /^[a-z_]{1,40}$/.test(datos.motivo)) ? datos.motivo : null;
    const prueba = {
        payload: {
            decision: datos.decision,
            cuenta: datos.cuenta,
            conf: datos.conf,
            margen: typeof datos.margen === "number" ? datos.margen : null,
            motivo: motivo,
