// GET /api/sesiones/:id/csv
// Valida que :id sea un entero de 1 a 2147483647 y construye la ruta fija
// /data/reportes/sesion-<id>.csv: nunca acepta nombres de archivo ni barras.
const crudo = (msg.req && msg.req.params) ? msg.req.params.id : undefined;
if (typeof crudo !== "string" || !/^[1-9][0-9]{0,9}$/.test(crudo) || Number(crudo) > 2147483647) {
    msg.statusCode = 400;
    msg.payload = { error: "id debe ser un entero positivo válido" };
    return [null, msg];
}
const id = Number(crudo);
msg.sesion_id = id;
msg.rutaPlantilla = "/api/sesiones/:id/csv";
msg.filename = "/data/reportes/sesion-" + id + ".csv";
msg.payload = null;
return [msg, null];

// Entrega los bytes exactos del CSV generado por reporte_csv.py (UTF-8 con BOM, CRLF y
// fórmulas neutralizadas), con Content-Disposition de descarga y nombre fijo sesion-<id>.csv.
const id = msg.sesion_id;
if (!Number.isSafeInteger(id) || id < 1 || id > 2147483647) {
    throw new Error("id de sesión inválido al responder el CSV");
}
if (!Buffer.isBuffer(msg.payload) && typeof msg.payload !== "string") {
    throw new Error("el nodo de lectura no devolvió el contenido del CSV");
}
msg.statusCode = 200;
msg.headers = {
    "content-type": "text/csv; charset=utf-8",
    "content-disposition": "attachment; filename=\"sesion-" + id + ".csv\""
};
return msg;

// Manejador de errores de la pestaña Asistencia.
// - Si Leer reporte CSV falla con ENOENT (la sesión sigue abierta, no existe o su archivo se
//   limpió), responde 404 sin ruido de 500 en el log.
// - Cualquier otro error registra solo la ruta plantilla y el SQLSTATE (o código POSIX de
//   archivo, o mensaje truncado con cuentas de 9 dígitos enmascaradas) y responde 500 JSON.
const error = msg.error || {};
const codigo = typeof error.code === "string" ? error.code : "";
const ruta = typeof msg.rutaPlantilla === "string" ? msg.rutaPlantilla : "/api/sesiones";

msg.headers = undefined;

if (ruta === "/api/sesiones/:id/csv" && (codigo === "ENOENT" || /\bENOENT\b/.test(String(error.message || "")))) {
    msg.statusCode = 404;
    msg.payload = { error: "El reporte CSV de esa sesión no está disponible (la sesión sigue abierta o no existe)" };
    return msg;
}

let causa;
if (/^[0-9A-Z]{5}$/.test(codigo)) {
    causa = "SQLSTATE " + codigo;
} else if (/^E[A-Z0-9_]{1,15}$/.test(codigo)) {
    causa = codigo;
} else if (typeof error.message === "string" && error.message !== "") {
    causa = error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120);
} else {
    causa = "error desconocido";
}
node.warn("GET " + ruta + " falló: " + causa);
msg.statusCode = 500;
msg.payload = {
    error: ruta === "/api/sesiones/:id/csv"
        ? "No se pudo leer el reporte CSV"
        : "No se pudo completar la operación en la base de datos"
};
return msg;

// Estado de un dispositivo: aula/vision/estado, aula/camara/estado y aula/actuador/estado (QoS 1,
// retenidos; contrato MQTT, secciones 3 y 4).
// Son estados, no eventos ni órdenes: su columna Retain es "sí", así que el retenido ES el estado
// actual y el descarte por retain de la sección 1 (solo para los tópicos con Retain = no) no aplica
// aquí. Tampoco los toca la limpieza de retenidos.
// Se descartan el payload vacío (en silencio: borrar el retenido del broker no borra el último estado
// que Node-RED ya tiene), lo que no es JSON, lo que no es un objeto y todo campo que no cumpla la tabla
// del contrato (tipo o valor). Un campo que el contrato no conoce se ignora y no se guarda (sección 1).
// Lo válido se guarda en el contexto del flujo (memoria) con la hora a la que lo recibió Node-RED:
//   flow.estado_vision, flow.estado_camara, flow.estado_actuadores = { datos, recibido_ms }
// Un estado nuevo reemplaza al anterior; uno descartado lo deja como estaba.
// Salida única: el descarte (nodo debug de consola). Su texto nombra el tópico y el campo, nunca el valor.
const MAX_CARACTERES = 1024; // el estado más grande (la visión) pesa unos 120 bytes
// ISO 8601 con zona, como la estampa la visión: "2026-11-04T09:12:33.120-06:00" (también "Z").
const TS = /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$/;

const booleano = (x) => typeof x === "boolean";
const entero = (min, max) => (x) => typeof x === "number" && Number.isInteger(x) && x >= min && x <= max;
const numero = (min, max) => (x) => typeof x === "number" && Number.isFinite(x) && x >= min && x <= max;
const uno = (...valores) => (x) => typeof x === "string" && valores.includes(x);
// Vacío es válido: la visión escribe "" cuando no tiene hora (ts) o modelo configurado. Solo ASCII imprimible
// (el nombre de un modelo lo es): así no pasan caracteres de control ni de formato (bidi, ancho cero) que
// confundirían lo que el frontend muestra.
const texto = (x) => typeof x === "string" && /^[\x20-\x7e]{0,100}$/.test(x);
const fecha = (x) => typeof x === "string" && TS.test(x) && !Number.isNaN(Date.parse(x));

// Un campo por renglón: [validador, obligatorio, omitir si es ""]. El firmware de la XIAO manda además
// camara, corte y nvs en aula/camara/estado (xiao.ino, construirLatido); la tabla del contrato no los lista.
const ESQUEMAS = {
    "aula/vision/estado": {
        clave: "estado_vision",
        campos: {
            en_linea: [booleano, true, false],
            ts: [(x) => x === "" || fecha(x), false, true],
            modo: [uno("inactivo", "pase", "enrolando"), false, false],
            galeria: [entero(0, 100000), false, false],
            modelo: [texto, false, false]
        }
    },
    "aula/camara/estado": {
        clave: "estado_camara",
        campos: {
            en_linea: [booleano, true, false],
            rssi: [entero(-200, 20), false, false],
            heap: [entero(0, 16777216), false, false],
            temp: [numero(-40, 150), false, false],
            camara: [booleano, false, false],
            corte: [booleano, false, false],
            nvs: [booleano, false, false]
        }
    },
    "aula/actuador/estado": {
        clave: "estado_actuadores",
        campos: {
            servo: [uno("abierto", "cerrado"), false, false],
            led: [uno("azul", "verde", "rojo", "ambar", "apagado"), false, false],
            luz: [entero(0, 1), false, false]
        }
    }
};

function descartar(motivo) {
    return [{ payload: "Descartado, " + msg.topic + ": " + motivo }];
}

const esquema = Object.prototype.hasOwnProperty.call(ESQUEMAS, msg.topic) ? ESQUEMAS[msg.topic] : null;
if (esquema === null) {
    return [{ payload: "Descartado, tópico que no es de estado" }];
}
if (msg.payload === "" || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0)) {
    return null;
}
if (typeof msg.payload !== "string") {
    return descartar("el payload no es texto");
}
if (msg.payload.length > MAX_CARACTERES) {
    return descartar("payload demasiado largo");
}
let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (e) {
    return descartar("no es JSON");
}
if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
    return descartar("no es un objeto JSON");
}

const estado = {};
let conCampos = false;
for (const campo of Object.keys(esquema.campos)) {
    const [valido, obligatorio, omitirVacio] = esquema.campos[campo];
    const valor = Object.prototype.hasOwnProperty.call(datos, campo) ? datos[campo] : undefined;
    if (valor === undefined) {
        if (obligatorio) {
            return descartar("falta " + campo);
        }
        continue;
    }
    if (!valido(valor)) {
        return descartar(campo + " fuera de la tabla del contrato");
    }
    if (omitirVacio && valor === "") {
        continue;
    }
    estado[campo] = valor;
    conCampos = true;
}
if (!conCampos) {
    return descartar("sin ningún campo del contrato");
}
flow.set(esquema.clave, { datos: estado, recibido_ms: Date.now() });
return null;

// Error de ejecución al guardar un estado (un fallo de la función, no un descarte). Se registra solo un texto
// fijo: nunca msg ni el mensaje de error, que podrían traer un trozo del payload recibido.
node.warn("Estado del sistema: no se guardó por un error de ejecución");
return null;

// Lee, uno por uno y con el nodo file in, los archivos de /proc y /sys de los que salen la temperatura, la CPU
// y la RAM de la placa (contrato MQTT, sección 5: aula/sistema/metricas). El contenedor de Node-RED ve
// /proc/stat y /proc/meminfo del host y puede leer /sys/class/thermal (se verificó desde dentro del
// contenedor), y una función no puede usar fs (functionExternalModules: false).
// Entrada: el inject (ciclo nuevo) o, en cada vuelta, la salida del file in (o de su catch, con msg.error).
// La lista de archivos es fija: ningún nombre viene de MQTT ni de HTTP. La lista se acorta en cada vuelta, así
// que el ciclo termina siempre; un archivo que no se pudo leer queda en null y no detiene el ciclo.
// El file in registra su propio error en cada lectura fallida aunque un catch lo recoja, y eso sería una línea de
// log por zona cada 10 s para siempre. Por eso una zona térmica que falla se deja de pedir (flow.fallos_zonas):
//   - ENOENT (no existe en este kernel): de forma permanente.
//   - Cualquier otro error 3 ciclos seguidos: 10 minutos, y entonces se vuelve a probar (una lectura; si falla otra vez,
//     otros 10 minutos; si sale bien, la zona vuelve a leerse en cada ciclo). Un ENOENT al volver a probar la hace permanente.
// Cada zona omitida deja un solo aviso (el reintento fallido no repite el aviso, solo deja el error del file in).
// El contexto del flujo está en memoria pero sobrevive a un despliegue (context.clean solo borra los contextos de
// flujos que ya no existen): solo reiniciar Node-RED vuelve a probar las zonas omitidas de forma permanente.
// /proc/stat y /proc/meminfo no se omiten nunca: si fallan, es un fallo real.
// Salida 1: el siguiente archivo para el file in (msg.filename). Salida 2: el ciclo completo, con
// msg.leidos = { ruta: texto | null }, para "Calcular métricas del sistema".
const ARCHIVOS = [
    "/proc/stat",
    "/proc/meminfo",
    "/sys/class/thermal/thermal_zone0/temp",
    "/sys/class/thermal/thermal_zone1/temp",
    "/sys/class/thermal/thermal_zone2/temp",
    "/sys/class/thermal/thermal_zone3/temp",
    "/sys/class/thermal/thermal_zone4/temp"
];

const ZONA = /^\/sys\/class\/thermal\/thermal_zone[0-9]+\/temp$/;
const MAX_FALLOS = 3;
const REINTENTO_MS = 10 * 60 * 1000;
const ahora = Date.now();
// { ruta: { n: fallos seguidos, ms: cuándo falló por última vez, permanente: true si fue ENOENT } }
const fallos = Object.assign({}, flow.get("fallos_zonas"));
// Omitida: permanente, o con 3 fallos y dentro de los 10 minutos desde el último. Un salto del reloj hacia atrás no
// la deja omitida para siempre (Date.now() puede saltar): se vuelve a probar.
const omitida = (ruta) => {
    const e = ZONA.test(ruta) ? fallos[ruta] : undefined;
    if (!e || e.n < MAX_FALLOS) {
        return false;
    }
    return e.permanente === true || (ahora - e.ms >= 0 && ahora - e.ms < REINTENTO_MS);
};

if (!Array.isArray(msg.pendientes) || msg.leidos === null || typeof msg.leidos !== "object") {
    msg.pendientes = ARCHIVOS.filter((ruta) => !omitida(ruta));
    msg.leidos = {};
} else if (ARCHIVOS.includes(msg.pedido)) {
    // Vuelta del file in: la clave es el archivo que se pidió, no lo que diga msg.filename.
    let contenido = null;
    if (msg.error === undefined) {
        if (typeof msg.payload === "string") {
            contenido = msg.payload;
        } else if (Buffer.isBuffer(msg.payload)) {
            contenido = msg.payload.toString("utf8");
        }
    }
    msg.leidos[msg.pedido] = contenido;
    if (ZONA.test(msg.pedido)) {
        const antes = fallos[msg.pedido] ? fallos[msg.pedido].n : 0;
        if (contenido !== null) {
            delete fallos[msg.pedido];
        } else {
            const error = msg.error !== null && typeof msg.error === "object" ? msg.error : {};
            const ausente = error.code === "ENOENT" || /ENOENT/.test(String(error.message));
            const previa = fallos[msg.pedido];
            const permanente = ausente || Boolean(previa && previa.permanente);
            const n = ausente ? MAX_FALLOS : Math.min(antes + 1, MAX_FALLOS);
            fallos[msg.pedido] = { n: n, ms: ahora, permanente: permanente };
            if (antes < MAX_FALLOS && n >= MAX_FALLOS) {
                node.warn("Zona térmica omitida: " + (permanente
                    ? "no existe (" + msg.pedido + "); no se vuelve a leer hasta reiniciar Node-RED"
                    : "no se puede leer (" + msg.pedido + "); se vuelve a probar cada 10 minutos"));
            }
        }
        flow.set("fallos_zonas", fallos);
    }
}
delete msg.error;
msg.payload = null;

if (msg.pendientes.length === 0) {
    delete msg.pendientes;
    delete msg.pedido;
    delete msg.filename;
    return [null, msg];
}
msg.pedido = msg.pendientes.shift();
msg.filename = msg.pedido;
return [msg, null];

// Temperatura, CPU y RAM de la placa a partir de lo que leyó "Siguiente archivo" (msg.leidos).
//   temp: la zona térmica más caliente del SoC (cada thermal_zone*/temp trae milésimas de °C), en °C con un
//         decimal. Una zona ilegible o fuera de -40 a 150 °C no cuenta.
//   cpu:  % de uso entre este ciclo y el anterior, con la línea "cpu" de /proc/stat (user, nice, system, idle,
//         iowait, irq, softirq y steal; guest ya va dentro de user). El primer ciclo solo toma la línea base
//         (sin aviso: es lo esperado al arrancar) y la primera métrica sale 10 s después. Si los contadores no
//         avanzan (o retroceden por un reinicio) no hay porcentaje: se toma una línea base nueva y queda un aviso.
//   ram:  % en uso = 1 - MemAvailable / MemTotal, de /proc/meminfo.
// Con las tres lecturas guarda el último valor en flow.metricas_sistema = { datos, recibido_ms } (lo lee la
// API) y saca el payload de aula/sistema/metricas {"ts","temp","cpu","ram"} (contrato MQTT, sección 5: cpu y
// ram enteros, temp con un decimal) y la fila para metricas_energia (origen 'sistema', solo temp_soc: cpu y ram
// no tienen columna).
// Salida 1: el mqtt out. Salida 2: msg.params = [temp] para el INSERT. Salida 3: aviso de por qué no hay
// métrica (nodo debug de consola), con texto fijo. El aviso de lo que no se pudo leer sale solo cuando cambia
// el conjunto de lo que falta (flow.falta_metricas, memoria) y se rearma cuando todo vuelve a leerse: un fallo
// permanente es una línea, no una cada 10 s. El de los contadores de la CPU que no avanzan sale en cada ciclo.
function leerCpu(texto) {
    if (typeof texto !== "string") {
        return null;
    }
    const m = /^cpu\s+([0-9]+(?:\s+[0-9]+){7})(?:\s|$)/.exec(texto);
    if (m === null) {
        return null;
    }
    const c = m[1].split(/\s+/).map(Number);
    if (!c.every((x) => Number.isSafeInteger(x))) {
        return null;
    }
    return { total: c.reduce((a, b) => a + b, 0), ocioso: c[3] + c[4] };
}

function leerRam(texto) {
    if (typeof texto !== "string") {
        return null;
    }
    const total = /^MemTotal:\s+([0-9]+)\s+kB$/m.exec(texto);
    const disponible = /^MemAvailable:\s+([0-9]+)\s+kB$/m.exec(texto);
    if (total === null || disponible === null || Number(total[1]) <= 0 || Number(disponible[1]) > Number(total[1])) {
        return null;
    }
    return (1 - Number(disponible[1]) / Number(total[1])) * 100;
}

function leerTemp(leidos) {
    let maxima = null;
    for (const ruta of Object.keys(leidos)) {
        const texto = leidos[ruta];
        if (!/^\/sys\/class\/thermal\/thermal_zone[0-9]+\/temp$/.test(ruta) || typeof texto !== "string") {
            continue;
        }
        if (!/^\s*-?[0-9]{1,7}\s*$/.test(texto)) {
            continue;
        }
        const grados = Number(texto) / 1000;
        if (grados >= -40 && grados <= 150 && (maxima === null || grados > maxima)) {
            maxima = grados;
        }
    }
    return maxima;
}

const leidos = msg.leidos !== null && typeof msg.leidos === "object" ? msg.leidos : {};
const cpuActual = leerCpu(leidos["/proc/stat"]);
const ram = leerRam(leidos["/proc/meminfo"]);
const temp = leerTemp(leidos);

const falta = [];
if (temp === null) { falta.push("la temperatura"); }
if (cpuActual === null) { falta.push("la CPU"); }
if (ram === null) { falta.push("la RAM"); }
if (falta.length > 0) {
    const conjunto = falta.join(", ");
    if (flow.get("falta_metricas") === conjunto) {
        return [null, null, null];
    }
    flow.set("falta_metricas", conjunto);
    return [null, null, { payload: "Métricas del sistema no publicadas: no se pudo leer " + conjunto }];
}
flow.set("falta_metricas", undefined);

const previo = flow.get("cpu_previo");
flow.set("cpu_previo", cpuActual);
if (previo === undefined || previo === null) {
    return [null, null, null]; // primer ciclo: solo la línea base, y es lo esperado al arrancar
}
if (!(cpuActual.total > previo.total)) {
    return [null, null, { payload: "Métricas del sistema no publicadas: los contadores de la CPU no avanzaron (se toma una línea base nueva)" }];
}
const inactivo = (cpuActual.ocioso - previo.ocioso) / (cpuActual.total - previo.total);
const cpu = Math.min(100, Math.max(0, (1 - inactivo) * 100));

const datos = { ts: new Date().toISOString(), temp: Math.round(temp * 10) / 10, cpu: Math.round(cpu), ram: Math.round(ram) };
flow.set("metricas_sistema", { datos: datos, recibido_ms: Date.now() });
return [{ payload: JSON.stringify(datos) }, { payload: null, params: [datos.temp] }, null];

// Error de ejecución (la base, sobre todo) en la rama de las métricas. Se registra solo el código SQLSTATE
// (cinco caracteres), o un mensaje truncado y sin secuencias de 9 dígitos: nunca msg ni msg.params.
// No se reintenta: es una medición, y la siguiente llega 10 s después.
const error = msg.error || {};
let causa;
if (typeof error.code === "string" && /^[0-9A-Z]{5}$/.test(error.code)) {
    causa = "SQLSTATE " + error.code;
} else if (typeof error.message === "string" && error.message !== "") {
    causa = error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120);
} else {
    causa = "error desconocido";
}
node.warn("Métricas del sistema: falló: " + causa);
return null;

// GET /api/sistema/estado: lo último que Node-RED sabe del servicio de visión, de la XIAO (cámara y
// actuadores) y de la placa, tal como lo guardaron "Guardar estado de un dispositivo" y "Calcular métricas del
// sistema" en el contexto del flujo (memoria). Solo lee: no consulta la base, no publica y no escribe contexto.
// Cada entrada es { recibido, datos }: `recibido` es la hora en que Node-RED recibió ese estado (ISO 8601, UTC;
// para las métricas, la hora en que las midió) y `datos`, solo los campos del contrato, copiados uno por uno.
// Si desde que arrancó Node-RED no llegó nada, o el valor guardado no se puede leer, es
// { recibido: null, datos: null }.
// El retenido que el broker entrega al conectar cuenta como recibido en ese momento: la hora es la de
// Node-RED, no la del dispositivo.
const CAMPOS = {
    estado_vision: ["ts", "en_linea", "modo", "galeria", "modelo"],
    estado_camara: ["en_linea", "rssi", "heap", "temp", "camara", "corte", "nvs"],
    estado_actuadores: ["servo", "led", "luz"],
    metricas_sistema: ["ts", "temp", "cpu", "ram"]
};

function leer(clave) {
    const e = flow.get(clave);
    if (e === undefined || e === null || typeof e !== "object" || typeof e.recibido_ms !== "number"
        || !Number.isFinite(e.recibido_ms) || e.datos === null || typeof e.datos !== "object") {
        return { recibido: null, datos: null };
    }
    const recibido = new Date(e.recibido_ms);
    if (Number.isNaN(recibido.getTime())) {
        return { recibido: null, datos: null };
    }
    const datos = {};
    for (const campo of CAMPOS[clave]) {
        if (e.datos[campo] !== undefined) {
            datos[campo] = e.datos[campo];
        }
    }
    return { recibido: recibido.toISOString(), datos: datos };
}
msg.statusCode = 200;
msg.payload = {
    vision: leer("estado_vision"),
    camara: leer("estado_camara"),
    actuadores: leer("estado_actuadores"),
    metricas: leer("metricas_sistema")
};
return msg;

// Error al armar la respuesta: se registra con texto fijo y se responde 500 sin detalle.
node.warn("GET /api/sistema/estado falló");
msg.statusCode = 500;
msg.payload = { error: "No se pudo leer el estado del sistema" };
return msg;

// POST /api/actuadores {"servo":"abrir","led":"verde","buzzer":1,"luz":0}
// Control manual de la XIAO desde el frontend. Cuerpo JSON (Content-Type: application/json) con al menos uno de
// estos campos y ninguno más, con el vocabulario que acepta el firmware (firmware/xiao/logica_actuadores.cpp y
// logica_luz.cpp; una prueba los lee): servo "abrir" (no hay "cerrar": el servo se cierra solo a los 3 s), led
// "azul", "verde", "rojo", "ambar" o "apagado", buzzer 0, 1 o 2 (enteros) y luz 0 o 1 (enteros).
// Lo que se publica en aula/actuador/cmd se reconstruye campo por campo, en un orden fijo: nunca se reenvía el
// cuerpo recibido. El mayor payload posible pesa unos 50 bytes y cabe en el búfer de 256 bytes de la XIAO.
// Límite: una orden por segundo, en cualquier campo. Las demás se descartan con 429 y Retry-After (no se encolan
// ni renuevan la ventana). Va aquí y no en un nodo delay porque una petición HTTP descartada sin responder
// se quedaría colgada: así la persona sabe que su orden no salió. Mismo método que el límite de `iniciar` de la
// pestaña Sesiones: flow.ultimo_cmd_ms (memoria) y Date.now(), que puede saltar, por eso solo se descarta si pasó
// entre 0 y 1 s (un salto acepta en vez de bloquear). Un cuerpo inválido no gasta la ventana.
// Salida 1: el mensaje para el mqtt out (solo payload). Salida 2: la respuesta HTTP (200, 400, 415 o 429).
// Nada de lo que llega se repite en las respuestas ni en el log: solo nombres de campos del contrato.
const CAMPOS = ["servo", "led", "buzzer", "luz"];
const LEDS = ["azul", "verde", "rojo", "ambar", "apagado"];
const VENTANA_MS = 1000;

function responder(codigo, cuerpo, cabeceras) {
    msg.statusCode = codigo;
    msg.payload = cuerpo;
    if (cabeceras !== undefined) {
        msg.headers = cabeceras;
    }
    return [null, msg];
}

// Solo application/json: los tipos que un formulario HTML de otro sitio puede enviar sin permiso (text/plain,
// urlencoded) se rechazan; la otra capa contra CSRF está en autenticacion-api.js (X-Pase-Lista y el mismo origen).
const tipo = String(msg.req.headers["content-type"] || "").split(";")[0].trim().toLowerCase();
if (tipo !== "application/json") {
    return responder(415, { error: "El Content-Type debe ser application/json" });
}
const cuerpo = msg.payload;
if (cuerpo === null || typeof cuerpo !== "object" || Array.isArray(cuerpo)) {
    return responder(400, { error: "El cuerpo debe ser un objeto JSON con servo, led, buzzer o luz" });
}
const claves = Object.keys(cuerpo);
if (claves.length === 0 || claves.some((c) => !CAMPOS.includes(c))) {
    return responder(400, { error: "El cuerpo solo admite servo, led, buzzer y luz, y al menos uno" });
}

const VALIDADORES = {
    servo: [(x) => x === "abrir", "servo solo admite \"abrir\" (el servo se cierra solo a los 3 s)"],
    led: [(x) => typeof x === "string" && LEDS.includes(x), "led debe ser azul, verde, rojo, ambar o apagado"],
    buzzer: [(x) => typeof x === "number" && Number.isInteger(x) && x >= 0 && x <= 2, "buzzer debe ser el entero 0, 1 o 2"],
    luz: [(x) => typeof x === "number" && Number.isInteger(x) && x >= 0 && x <= 1, "luz debe ser el entero 0 o 1"]
};
const orden = {};
for (const campo of CAMPOS) {
    if (!Object.prototype.hasOwnProperty.call(cuerpo, campo)) {
        continue;
    }
    const [valido, texto] = VALIDADORES[campo];
    if (!valido(cuerpo[campo])) {
        return responder(400, { error: texto });
    }
    orden[campo] = cuerpo[campo];
}

const ahora = Date.now();
const ultima = flow.get("ultimo_cmd_ms");
if (typeof ultima === "number" && ahora - ultima >= 0 && ahora - ultima < VENTANA_MS) {
    return responder(429, { error: "Demasiado rápido: espera un segundo entre órdenes a los actuadores" }, { "retry-after": "1" });
}
flow.set("ultimo_cmd_ms", ahora);

node.log("Orden manual a los actuadores: " + Object.keys(orden).join(", "));
msg.statusCode = 200;
msg.payload = { publicado: orden };
return [{ payload: JSON.stringify(orden) }, msg];

// Error de ejecución al validar o responder: se registra con texto fijo (nunca msg ni el cuerpo) y se responde
// 500 sin detalle.
node.warn("POST /api/actuadores falló");
delete msg.error;
msg.statusCode = 500;
msg.payload = { error: "No se pudo procesar la orden a los actuadores" };
return msg;

// POST /api/enrolamiento/probar
// "Probar reconocimiento" del frontend: pide a la visión un reconocimiento inmediato de quien esté frente a
// la cámara, sin marcar asistencia y sin necesitar una sesión abierta. Sin cuerpo (como "Cancelar inscripción", el
// cuerpo no se lee: nada de lo que llegue viaja a la visión; la orden no lleva cuenta).
// Publica aula/vision/cmd {"accion":"probar"} y deja en flow.prueba que hay una prueba pendiente. La respuesta
// del resultado no sale de aquí: la guarda "Guardar resultado de la prueba" y la lee GET /api/enrolamiento/prueba.
// Rechazos, en este orden:
//   - 409 registro_abierto: con un registro abierto la visión está ocupada con él y contestaría "ocupado".
//   - 409 prueba_pendiente: ya hay una prueba esperando resultado. Espera como máximo 15 s: la visión enciende la
//     luz, espera 0,3 s, toma una ráfaga de 4 fotos (con 2 s de plazo HTTP por foto a la XIAO y, si acaba de
//     disparar otra, hasta 3 s de pausa entre ráfagas) y corre la NPU; pasado ese plazo se da por perdida
//     para que un resultado que nunca llegó no bloquee la prueba para siempre.
//   - 429: otra solicitud a menos de 3 s de la anterior (la pausa mínima entre ráfagas de la visión). Va aquí y no
//     en un nodo delay porque una petición HTTP descartada sin responder se quedaría colgada. Mismo método que
//     el límite de la pestaña Actuadores: flow.prueba.solicitado_ms y Date.now(), que puede saltar, por eso solo cuenta
//     si pasaron entre 0 y el plazo (un salto acepta en vez de bloquear). Un rechazo no renueva la ventana.
// Una solicitud aceptada borra el resultado anterior: el que llegue será el de esta prueba.
// Salida 1: orden a aula/vision/cmd. Salida 2: respuesta HTTP (202, 409 o 429).
const ESPERA_MAX_MS = 15 * 1000;
const VENTANA_MS = 3 * 1000;

function responder(codigo, cuerpo, cabeceras) {
    msg.statusCode = codigo;
    msg.payload = cuerpo;
    if (cabeceras !== undefined) {
        msg.headers = cabeceras;
    }
    return [null, msg];
}

const insc = flow.get("inscripcion");
if (insc && insc.abierto === true) {
    return responder(409, {
        error: "Hay un registro abierto y la visión está ocupada con él: termínalo o cancélalo antes de probar el reconocimiento",
        motivo: "registro_abierto"
    });
}
const ahora = Date.now();
const previa = flow.get("prueba");
const solicitada = previa && typeof previa.solicitado_ms === "number" ? previa.solicitado_ms : null;
const transcurrido = solicitada === null ? null : ahora - solicitada;
if (previa && previa.pendiente === true && transcurrido !== null && transcurrido >= 0 && transcurrido < ESPERA_MAX_MS) {
    return responder(409, {
        error: "Ya hay una prueba en curso: espera su resultado",
        motivo: "prueba_pendiente",
        solicitado: new Date(solicitada).toISOString()
    });
}
if (transcurrido !== null && transcurrido >= 0 && transcurrido < VENTANA_MS) {
    return responder(429, { error: "Demasiado rápido: espera unos segundos entre pruebas" }, { "retry-after": String(Math.ceil((VENTANA_MS - transcurrido) / 1000)) });
}

flow.set("prueba", { solicitado_ms: ahora, pendiente: true, resultado: null });
node.log("Prueba de reconocimiento solicitada");
const orden = {
    topic: "aula/vision/cmd",
    payload: JSON.stringify({ accion: "probar" }),
    qos: 1,
    retain: false
};
msg.statusCode = 202;
msg.payload = { pendiente: true, solicitado: new Date(ahora).toISOString() };
return [orden, msg];

// GET /api/enrolamiento/prueba: solo lectura. Devuelve lo último que se sabe de la prueba de reconocimiento:
// {pendiente, solicitado, resultado: {decision, cuenta, nombre, conf, margen, motivo, lat_ms, recibido} | null}
//   - pendiente: se pidió una prueba hace menos de 15 s y aún no hay resultado (pasado el plazo, false).
//   - solicitado: ISO 8601 UTC de la última solicitud, o null si no hubo ninguna desde que arrancó Node-RED.
//     Con pendiente false, solicitado distinto de null y resultado null, la visión no contestó a tiempo.
//   - resultado: el de la última prueba (un rechazo "ocupado" llega como decision "error", motivo "ocupado" y
//     lat_ms null); recibido es la hora en que Node-RED lo recibió. `cuenta` solo sale con reconocido o dudoso
//     (con desconocido, la visión manda su mejor candidato para auditoría y aquí no se muestra).
// El nombre sale de la tabla de alumnos, solo para esa cuenta: con reconocido o dudoso el cuerpo espera al SELECT
// (salida 1) y "Completar la prueba con el nombre" lo termina; con cualquier otra cosa responde aquí (salida 2).
// Cada campo se copia por su nombre: nunca sale de aquí un embedding.
// Salida 1: SELECT del nombre (msg.params = [cuenta], msg.cuerpo). Salida 2: respuesta HTTP.
const ESPERA_MAX_MS = 15 * 1000;
const CON_CUENTA = ["reconocido", "dudoso"];
const iso = (ms) => new Date(ms).toISOString();

function responder(cuerpo) {
    msg.statusCode = 200;
    msg.payload = cuerpo;
    return [null, msg];
}

const prueba = flow.get("prueba");
if (!prueba || typeof prueba.solicitado_ms !== "number") {
    return responder({ pendiente: false, solicitado: null, resultado: null });
}
const transcurrido = Date.now() - prueba.solicitado_ms;
const pendiente = prueba.pendiente === true && transcurrido >= 0 && transcurrido < ESPERA_MAX_MS;
const r = prueba.resultado;
let resultado = null;
if (r && typeof r === "object") {
    const lat = r.lat_ms && typeof r.lat_ms === "object" ? r.lat_ms : null;
    resultado = {
        decision: r.decision,
        cuenta: CON_CUENTA.includes(r.decision) && typeof r.cuenta === "string" ? r.cuenta : null,
        nombre: null,
        conf: r.conf ?? null,
        margen: r.margen ?? null,
        motivo: r.motivo ?? null,
        lat_ms: lat === null ? null : { cap: lat.cap ?? null, det: lat.det ?? null, emb: lat.emb ?? null, total: lat.total ?? null },
        recibido: iso(r.recibido_ms)
    };
}
const cuerpo = { pendiente: pendiente, solicitado: iso(prueba.solicitado_ms), resultado: resultado };
if (resultado !== null && resultado.cuenta !== null) {
    msg.params = [resultado.cuenta];
    msg.cuerpo = cuerpo;
    return [msg, null];
}
return responder(cuerpo);

// Respuesta del SELECT del nombre (una fila {nombre}, o ninguna si la cuenta ya no está en la lista): lo pone
// en el cuerpo de GET /api/enrolamiento/prueba y responde 200. Sin fila, nombre null. La consulta solo lee el
// nombre: nunca el embedding.
const cuerpo = msg.cuerpo;
if (!cuerpo || !cuerpo.resultado) {
    throw new Error("falta el cuerpo de la prueba");
}
const fila = Array.isArray(msg.payload) ? msg.payload[0] : undefined;
cuerpo.resultado.nombre = fila && typeof fila.nombre === "string" ? fila.nombre : null;
msg.statusCode = 200;
msg.payload = cuerpo;
return msg;

// Guarda el resultado de la prueba de reconocimiento en flow.prueba (memoria), con la hora en que se recibió.
// Llega por dos caminos y en ambos solo cuenta si hay una prueba pendiente (POST /api/enrolamiento/probar, hace
// menos de 15 s y sin resultado todavía):
//   1. El resultado de modo "prueba" (aula/vision/resultado), que reenvía la 4.ª salida de "Validar resultado de visión"
//      (pestaña Pase de lista) por un enlace: ya viene validado (decision, cuenta, conf, margen, motivo, lat_ms y ts_ms,
//      su `ts` en ms). Un resultado cuyo ts es anterior a la solicitud (con 2 s de margen) es de otra prueba y se
//      descarta: así uno rezagado de una prueba vencida no contesta a la siguiente.
//   2. El rechazo de la visión cuando está ocupada (aula/vision/enrolamiento, el mismo mqtt in que alimenta el progreso
//      del registro): estado "error", motivo "ocupado", paso 0 y cuenta vacía (la orden no lleva cuenta; la visión no la
//      repite si no es válida). Se guarda como decision "error" con motivo "ocupado". El "ocupado" de un enrolar lleva
//      cuenta y no entra. El resto del tráfico de ese tópico es el progreso del registro: se ignora en silencio.
// Esta función no escribe en la base, no publica y no toca asistencias, intentos ni los actuadores. `cuenta` solo se conserva
// con reconocido o dudoso (con desconocido es el mejor candidato para auditoría). Un descarte o un registro nunca repite
// la cuenta.
// Salida 1: avisos de descarte (nodo debug de consola, sin contenido del mensaje).
const ESPERA_MAX_MS = 15 * 1000;
const MARGEN_TS_MS = 2000;
const MAX_CARACTERES = 32768;
const DECISIONES = ["reconocido", "dudoso", "desconocido", "sin_rostro", "imagen_insuficiente", "error"];
const CON_CUENTA = ["reconocido", "dudoso"];
const CUENTA = /^[0-9]{9}$/;
const MOTIVO = /^[a-z_]{1,40}$/;

const ahora = Date.now();
const prueba = flow.get("prueba");
const transcurrido = prueba && typeof prueba.solicitado_ms === "number" ? ahora - prueba.solicitado_ms : null;
const vigente = Boolean(prueba) && prueba.pendiente === true && transcurrido !== null && transcurrido >= 0 && transcurrido < ESPERA_MAX_MS;

function cerrar(resultado) {
    flow.set("prueba", { solicitado_ms: prueba.solicitado_ms, pendiente: false, resultado: { ...resultado, recibido_ms: ahora } });
    node.log("Prueba de reconocimiento: " + resultado.decision);
    return null;
}

if (msg.topic === "aula/vision/enrolamiento") {
    if (!vigente || msg.retain === true || typeof msg.payload !== "string" || msg.payload.length > MAX_CARACTERES) {
        return null;
    }
    let datos;
    try {
        datos = JSON.parse(msg.payload);
    } catch (e) {
        return null;
    }
    if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
        return null;
    }
    if (datos.cuenta !== "" || datos.estado !== "error" || datos.motivo !== "ocupado" || datos.paso !== 0) {
        return null;
    }
    const instante = typeof datos.ts === "string" ? Date.parse(datos.ts) : Number.NaN;
    if (Number.isNaN(instante) || instante < prueba.solicitado_ms - MARGEN_TS_MS) {
        return null;
    }
    return cerrar({ decision: "error", cuenta: null, conf: null, margen: null, motivo: "ocupado", lat_ms: null });
}

function descartar(motivo) {
    return { payload: "Descartado, " + motivo };
}
const d = msg.payload;
if (d === null || typeof d !== "object" || !DECISIONES.includes(d.decision) || typeof d.ts_ms !== "number") {
    return descartar("el resultado de prueba no tiene la forma esperada");
}
if (!vigente) {
    return descartar("llegó un resultado de prueba sin una prueba pendiente");
}
if (d.ts_ms < prueba.solicitado_ms - MARGEN_TS_MS) {
    return descartar("el resultado de prueba es anterior a la solicitud");
}
const finito = (x) => typeof x === "number" && Number.isFinite(x);
const etapa = (x) => (finito(x) && x >= 0 && x <= 600000 ? x : null);
const lat = d.lat_ms !== null && typeof d.lat_ms === "object" ? d.lat_ms : null;
return cerrar({
    decision: d.decision,
    cuenta: CON_CUENTA.includes(d.decision) && typeof d.cuenta === "string" && CUENTA.test(d.cuenta) ? d.cuenta : null,
    conf: finito(d.conf) && d.conf >= -1 && d.conf <= 1 ? d.conf : null,
    margen: finito(d.margen) ? d.margen : null,
    motivo: typeof d.motivo === "string" && MOTIVO.test(d.motivo) ? d.motivo : null,
    lat_ms: lat === null ? null : { cap: etapa(lat.cap), det: etapa(lat.det), emb: etapa(lat.emb), total: etapa(lat.total) }
});

// Error en la prueba de reconocimiento (solicitud o estado): se registra el mensaje truncado, sin secuencias
// de 9 dígitos (números de cuenta), y se responde 500. No se repite ni el cuerpo ni el payload.
const error = msg.error || {};
const causa = (typeof error.message === "string" && error.message !== "")
    ? error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120)
    : "error desconocido";
node.warn("Prueba de reconocimiento falló: " + causa);
msg.statusCode = 500;
msg.payload = { error: "No se pudo completar la prueba de reconocimiento" };
return msg;

// Error al guardar el resultado de la prueba: solo se registra el mensaje truncado, sin secuencias de 9 dígitos.
// Nada responde aquí (el mensaje no viene de una petición HTTP) y el mensaje original, que lleva la cuenta, no sigue.
const error = msg.error || {};
const causa = (typeof error.message === "string" && error.message !== "")
    ? error.message.replace(/[0-9]{9}/g, "*********").slice(0, 120)
    : "error desconocido";
node.warn("Guardar el resultado de la prueba falló: " + causa);
return null;

// Al arrancar Node-RED, y en un despliegue completo o que reinicie esta pestaña (el inject corre una vez al iniciar el
// nodo): las miniaturas del pase de lista viven solo en memoria y se borran (contexto global `miniaturas_pase`; ver
// "Retroalimentación del pase"). Un despliegue que no toque esta pestaña no las borra, a propósito: quitaría las fotos
// de la clase en curso. No tiene salida.
global.set("miniaturas_pase", undefined);
node.log("Arranque: se borran las miniaturas del pase de lista");
return null;
